import subprocess, os, shutil, pathlib, sys, json
BIN="/workspace/executable"
def run_case(name, files, args_extra=None, cwd_files=None):
    base=pathlib.Path(f"/tmp/cases/{name}")
    shutil.rmtree(base, ignore_errors=True)
    inp=base/"input"; inp.mkdir(parents=True)
    for rel, content in files.items():
        p=inp/rel; p.parent.mkdir(parents=True, exist_ok=True)
        if isinstance(content, bytes): p.write_bytes(content)
        else: p.write_text(content)
    args=args_extra or []
    r=subprocess.run([BIN]+args+[str(inp), str(base/"output")], capture_output=True, text=True)
    print(f"=== {name} exit={r.returncode} ===")
    if r.stdout: print("STDOUT:", r.stdout[:3000])
    if r.stderr: print("STDERR:", r.stderr[:3000])
    out=base/"output"
    if out.exists():
        for p in sorted(out.rglob("*")):
            if p.is_file(): print(" ", p.relative_to(out), p.stat().st_size)
    return base, r
PY
