{"command":"cat > app/yaml_engine.py << 'PY'
import re

class YamlError(Exception):
    def __init__(self, message, kind="display", line=None, col=None):
        super().__init__(message)
        self.message=message
        self.kind=kind
        self.line=line
        self.col=col

def _strip_comment(s):
    # remove # comment when preceded by space and not in quotes (caller handles quoted)
    in_s=False; in_d=False; esc=False
    for i,ch in enumerate(s):
        if esc:
            esc=False; continue
        if ch=='\\' and in_d: esc=True; continue
        if ch=="'" and not in_d: in_s=not in_s
        elif ch=='"' and not in_s: in_d=not in_d
        elif ch=='#' and not in_s and not in_d and (i==0 or s[i-1] in ' \t'):
            return s[:i].rstrip()
    return s

def parse_scalar(s, line_no=1):
    s=s.strip()
    if s=='' or s=='~' or s.lower()=='null':
        return None
    if s.startswith('"') and len(s)>=2:
        # double quoted yaml string
        try:
            out=''; i=1
            while i < len(s):
                ch=s[i]
                if ch=='\\' and i+1<len(s):
                    nxt=s[i+1]
                    mp={'n':'\n','t':'\t','r':'\r','\\':'\\','"':'"',"'":"'",'0':'\0','a':'\a','b':'\b','f':'\f','v':'\v'}
                    if nxt in mp: out+=mp[nxt]; i+=2; continue
                    if nxt in ('x','u','U'):
                        ln={'x':2,'u':4,'U':8}[nxt]; out+=chr(int(s[i+2:i+2+ln],16)); i+=2+ln; continue
                    out+=nxt; i+=2; continue
                if ch=='"':
                    break
                out+=ch; i+=1
            return out
        except Exception:
            return s
    if s.startswith("'") and len(s)>=2:
        # single quoted, '' escape
        end=1; out=''
        while end < len(s):
            if s[end]=="'":
                if end+1<len(s) and s[end+1]=="'": out+="'"; end+=2; continue
                break
            out+=s[end]; end+=1
        return out
    low=s.lower()
    if low=='true': return True
    if low=='false': return False
    # flow collections
    if s.startswith('[') or s.startswith('{'):
        return parse_flow(s, line_no)
    # numbers
    if re.fullmatch(r'[-+]?\d+', s):
        try: return int(s)
        except: pass
    if re.fullmatch(r'[-+]?(\d+\.\d*|\.\d+|\d+)([eE][-+]?\d+)?', s) and any(c in s for c in '.eE'):
        try: return float(s)
        except: pass
    if s in ('.inf','-.inf','.nan'): return float('inf') if not s.startswith('-') else float('-inf')
    return s

def _split_flow(s):
    parts=[]; depth=0; in_s=False; in_d=False; esc=False; start=0
    for i,ch in enumerate(s):
        if esc: esc=False; continue
        if ch=='\\' and in_d: esc=True; continue
        if ch=="'" and not in_d: in_s=not in_s
        elif ch=='"' and not in_s: in_d=not in_d
        elif not in_s and not in_d:
            if ch in '[{': depth+=1
            elif ch in ']}': depth-=1
            elif ch==',' and depth==0:
                parts.append(s[start:i]); start=i+1
    parts.append(s[start:])
    return parts

def parse_flow(s, line_no=1):
    s=s.strip()
    if s.startswith('['):
        if not s.rstrip().endswith(']'):
            raise YamlError(f"did not find expected ',' or ']' at line {line_no+1} column 1, while parsing a flow sequence at line {line_no} column 1")
        inner=s[1:-1].strip()
        if not inner: return []
        return [parse_scalar(p.strip(), line_no) if not (p.strip().startswith('[') or p.strip().startswith('{')) else parse_flow(p.strip(), line_no) for p in _split_flow(inner)]
    if s.startswith('{'):
        if not s.rstrip().endswith('}'):
            raise YamlError("did not find expected ',' or '}' while parsing a flow mapping")
        inner=s[1:-1].strip(); d={}
        if not inner: return d
        for p in _split_flow(inner):
            if ':' in p:
                k,v=p.split(':',1); d[parse_scalar(k.strip(),line_no)]=parse_scalar(v.strip(),line_no)
        return d
    return parse_scalar(s, line_no)

class _Line:
    __slots__=('indent','content','no','raw')
    def __init__(self,indent,content,no,raw): self.indent=indent; self.content=content; self.no=no; self.raw=raw

def _prepare_lines(text):
    lines=[]
    for idx, raw in enumerate(text.splitlines(),1):
        if raw.strip()=='' : continue
        if raw.lstrip().startswith('#'): continue
        # document markers
        if raw.strip() in ('---','...'): continue
        stripped=raw.lstrip(' ')
        indent=len(raw)-len(stripped)
        # tabs as indent not supported well
        lines.append(_Line(indent, stripped.rstrip(), idx, raw))
    return lines

def parse_yaml(text):
    lines=_prepare_lines(text)
    if not lines: return None
    # top-level scalar?
    if len(lines)==1 and ':' not in lines[0].content and not lines[0].content.startswith('- '):
        return parse_scalar(lines[0].content, lines[0].no)
    val, idx = _parse_block(lines,0,lines[0].indent)
    return val

def _parse_block(lines, idx, indent):
    if idx>=len(lines): return None, idx
    if lines[idx].indent < indent: return None, idx
    # sequence
    if lines[idx].content.startswith('- ') or lines[idx].content=='-':
        return _parse_seq(lines, idx, indent)
    # mapping if contains : (not in quotes) followed by space/end
    if _is_mapping_line(lines[idx].content):
        return _parse_map(lines, idx, indent)
    # scalar possibly multiline plain: join lines at same indent
    parts=[lines[idx].content]; idx+=1
    while idx<len(lines) and lines[idx].indent>=indent and not _is_mapping_line(lines[idx].content) and not lines[idx].content.startswith('- '):
        parts.append(lines[idx].content); idx+=1
    return parse_scalar(' '.join(parts), lines[idx-1].no), idx

def _is_mapping_line(content):
    # find colon outside quotes/flow
    in_s=False; in_d=False; depth=0
    for i,ch in enumerate(content):
        if ch=="'" and not in_d: in_s=not in_s
        elif ch=='"' and not in_s: in_d=not in_d
        elif not in_s and not in_d:
