    # ---- table ----
    def _split_row(self,line):
        s=line.strip()
        if s.startswith('|'): s=s[1:]
        if s.endswith('|') and not s.endswith('\\|'): s=s[:-1]
        cells=[]; cur=''; i=0; in_code=False
        while i < len(s):
