def slugify(text):
    if text is None: return ""
    s=str(text)
    # transliteration
    import unicodedata
    s=unicodedata.normalize('NFKD', s)
    s=''.join(c for c in s if not unicodedata.combining(c))
    # some special letters
    s=s.replace('ß','ss').replace('æ','ae').replace('Æ','ae').replace('œ','oe').replace('Œ','oe').replace('ø','o').replace('Ø','o').replace('đ','d').replace('Đ','d').replace('ł','l').replace('Ł','l')
    s=s.encode('ascii','ignore').decode('ascii')
    s=s.lower()
    s=re.sub(r'[^a-z0-9]+','-',s)
    return s.strip('-')

def wiki_slug(text):
    # observed algorithm: html-escape text, percent-encode spaces/non-ascii, then slugify
    esc=htmlmod.escape(str(text), quote=False)
    out=[]
    for ch in esc:
        if ch==' ' or ord(ch)>127:
            for b in ch.encode('utf-8'):
                out.append(f"%{b:02X}")
        else:
            out.append(ch)
    return slugify(''.join(out))

def striptags(html):
    if html is None: return ""
    s=re.sub(r'<[^>]*>','',str(html))
    return htmlmod.unescape(s)

def escape_html_text(s):
    return str(s).replace('&','&amp;').replace('<','&lt;').replace('>','&gt;').replace('"','&quot;')

def escape_attr(s):
    return escape_html_text(s)

class Ref:
    def __init__(self, dest,title): self.dest=dest; self.title=title

