                    self.opts[k].update(v)
                else:
                    self.opts[k]=v
        self.refs={}
        self.footnote_defs={}
        self.footnote_order=[]  # labels in ref order
        self.footnote_ref_counts={}
        self.heading_slugs={}
        self.headings=[]  # list (level, text, slug)

    def ext(self,name): return bool(self.opts.get("extension",{}).get(name, False))
    def render_opt(self,name): return bool(self.opts.get("render",{}).get(name, False))

    # ---------- Main ----------
    def render(self, text):
        self.refs={}; self.footnote_defs={}; self.footnote_order=[]; self.footnote_ref_counts={}; self.heading_slugs={}; self.headings=[]
        if text is None: text=""
        text=text.replace('\r\n','\n').replace('\r','\n')
        lines=text.split('\n')
        # pre-scan defs (outside fences)
        lines=self._extract_defs(lines)
        html=self._parse_blocks(lines, tight=False)
        # footnotes section
        if self.ext("footnotes") and self.footnote_order:
            parts=['<section class="footnotes" data-footnotes>\n<ol>\n']
            for idx,label in enumerate(self.footnote_order,1):
                content=self.footnote_defs[label]
                # render def content as blocks (it may be inline text)
                inner=self._parse_blocks(content.split('\n'), tight=False)
                # append backref to last </p> or at end
                back=f'<a href="#fnref-{idx}" class="footnote-backref" data-footnote-backref data-footnote-backref-idx="{idx}" aria-label="Back to reference {idx}">\u21a9</a>'
                if '</p>' in inner:
                    pos=inner.rfind('</p>'); inner=inner[:pos].rstrip() + ' ' + back + inner[pos:]
                else:
                    inner=inner.rstrip() + back + '\n'
                parts.append(f'<li id="fn-{idx}">\n{inner}</li>\n')
            parts.append('</ol>\n</section>\n')
            html+=''.join(parts)
        return html

    def _extract_defs(self, lines):
        out=[]; i=0; in_fence=False; fence_char=None; fence_len=0
        while i < len(lines):
            line=lines[i]
            fm=re.match(r'^( {0,3})(`{3,}|~{3,})', line)
            if fm:
                marker=fm.group(2)
                if not in_fence: in_fence=True; fence_char=marker[0]; fence_len=len(marker)
                elif marker[0]==fence_char and len(marker)>=fence_len: in_fence=False
                out.append(line); i+=1; continue
            if in_fence:
                out.append(line); i+=1; continue
            # footnote def
            if self.ext("footnotes"):
                m=re.match(r'^ {0,3}\[\^([^\]]+)\]:[ \t]?(.*)$', line)
                if m:
                    label=m.group(1); content=m.group(2)
                    # collect continuation indented (2 spaces?) or blank+indented - simplify: lines indented >=2 or blank followed by indented
                    j=i+1; extra=[]
                    while j < len(lines):
                        nl=lines[j]
                        if nl.strip()=='':
                            # peek next indented
                            if j+1 < len(lines) and re.match(r'^ {2,}\S', lines[j+1]): extra.append(''); j+=1; continue
                            break
                        if re.match(r'^ {2,}', nl):
                            extra.append(re.sub(r'^ {2,4}','',nl)); j+=1; continue
                        break
                    full=content + ('\n'+'\n'.join(extra) if extra else '')
                    self.footnote_defs[label]=full.strip('\n')
                    i=j; continue
            # link ref def: may span 2 lines for title
            m=re.match(r'^ {0,3}\[([^\]]+)\]:[ \t]*(.*)$', line)
            if m and not m.group(1).startswith('^'):
                rest=m.group(2)
                parsed=self._parse_link_dest_title(rest)
                if parsed is not None:
                    dest,title,consumed = parsed
                    label=self._normalize_label(m.group(1))
                    if label not in self.refs:
                        self.refs[label]=Ref(dest,title)
                    i+=1; continue
                elif rest=='' and i+1 < len(lines):
                    # dest on next line
                    parsed=self._parse_link_dest_title(lines[i+1].strip())
                    if parsed is not None:
                        dest,title,_=parsed; label=self._normalize_label(m.group(1))
                        if label not in self.refs: self.refs[label]=Ref(dest,title)
                        i+=2; continue
            out.append(line); i+=1
        return out

    def _normalize_label(self,label):
        return re.sub(r'\s+',' ',label.strip()).lower()

    def _parse_link_dest_title(self, s):
        s=s.strip()
        if not s: return None
        title=None; dest=''
        if s.startswith('<'):
            end=s.find('>')
            if end==-1: return None
            dest=s[1:end]; rest=s[end+1:].strip()
        else:
            # bare dest up to whitespace (balance parens naive)
            m=re.match(r'(\S+)', s); 
            if not m: return None
            dest=m.group(1); rest=s[m.end():].strip()
            # handle dest wrapped in parens? comrak strips outer? leave
        if rest:
            # title in "..." '...' (...)
            if (rest.startswith('"') and rest.endswith('"')) or (rest.startswith("'") and rest.endswith("'")) or (rest.startswith('(') and rest.endswith(')')):
                title=rest[1:-1]
            else:
                return None
        return dest,title,True

    # ---------- Blocks ----------
    def _parse_blocks(self, lines, tight=False):
        out=[]; i=0
        while i < len(lines):
            line=lines[i]
            if line.strip()=='':
                i+=1; continue
            # fenced code
            m=re.match(r'^( {0,3})(`{3,}|~{3,})[ \t]*(.*)$', line)
            if m:
                indent=len(m.group(1)); fence=m.group(2); ch=fence[0]; flen=len(fence); info=m.group(3).strip()
                lang=info.split()[0] if info else ''
                code_lines=[]; i+=1
                while i < len(lines):
                    cm=re.match(r'^ {0,3}(`{3,}|~{3,})[ \t]*$', lines[i])
                    if cm and cm.group(1)[0]==ch and len(cm.group(1))>=flen:
                        i+=1; break
                    # strip up to indent spaces
                    cl=lines[i]
                    if indent and cl.startswith(' '*indent): cl=cl[indent:]
                    code_lines.append(cl); i+=1
                code='\n'.join(code_lines)
                if code_lines: code+='\n'
                cls=f' class="language-{escape_attr(lang)}"' if lang else ''
                out.append(f'<pre><code{cls}>{escape_html_text(code)}</code></pre>\n')
                continue
            # HTML block
            html_block, consumed = self._try_html_block(lines,i)
            if html_block is not None:
                out.append(html_block); i+=consumed; continue
            # ATX heading
            m=re.match(r'^ {0,3}(#{1,6})(?:[ \t]+(.*?)|[ \t]*)$', line)
            if m and not (len(m.group(1))>=1 and m.group(2) is None and False):
                # need space or empty unless # alone; also #NoSpace is heading in comrak? observed #NoSpace treated as heading for title extraction but block? earlier #NoSpace as first line removed; in body, comrak requires space? Let's test mental: CommonMark #NoSpace is not heading. But marmite title removed it. For in-body, use CommonMark: require space unless line is only hashes
                raw=m.group(2)
                if raw is None:
                    # only hashes
                    content=''
                else:
                    content=raw.strip()
                    content=re.sub(r'[ \t]+#+[ \t]*$','',content)
                level=len(m.group(1))
                if raw is None or line.strip().lstrip('#').strip()=='' or re.match(r'^ {0,3}#{1,6}[ \t]', line) or re.match(r'^ {0,3}#{1,6}$',line.strip()):
                    out.append(self._render_heading(level, content)); i+=1; continue
                # else fall through to paragraph
            # thematic break
            if self._is_thematic(line):
                out.append('<hr />\n'); i+=1; continue
            # blockquote
            if re.match(r'^ {0,3}>[ \t]?', line):
                qlines=[]; j=i
                while j < len(lines):
                    l=lines[j]
                    if re.match(r'^ {0,3}>[ \t]?', l):
                        qlines.append(re.sub(r'^ {0,3}>[ \t]?','',l)); j+=1
                    elif l.strip()=='' :
                        break
                    elif qlines and not self._is_block_start(l):
                        # lazy continuation
                        qlines.append(l); j+=1
                    else:
                        break
                inner_html=self._parse_blocks(qlines, tight=False)
                if self.ext("alerts"):
                    alert=self._try_alert(qlines, inner_html)
                    if alert is not None:
                        out.append(alert); i=j; continue
                out.append(f'<blockquote>\n{inner_html}</blockquote>\n'); i=j; continue
            # list
            if self._is_list_start(line):
                html_list, consumed=self._parse_list(lines,i)
                out.append(html_list); i+=consumed; continue
            # table: current line and next delimiter
            if self.ext("table") and i+1 < len(lines) and '|' in line and self._is_table_delim(lines[i+1]):
                html_table, consumed=self._parse_table(lines,i)
                out.append(html_table); i+=consumed; continue
            # indented code (not after paragraph because blocks separated)
            if line.startswith('    ') or line.startswith('\t'):
                code=[]; j=i
                while j < len(lines):
                    l=lines[j]
                    if l.startswith('    '): code.append(l[4:]); j+=1
                    elif l.startswith('\t'): code.append(l[1:]); j+=1
                    elif l.strip()=='':
                        # include if followed by indented
                        if j+1 < len(lines) and (lines[j+1].startswith('    ') or lines[j+1].startswith('\t')): code.append(''); j+=1
                        else: break
                    else: break
                while code and code[-1]=='': code.pop()
                out.append(f'<pre><code>{escape_html_text(chr(10).join(code))}\n</code></pre>\n'); i=j; continue
            # paragraph / setext / description list
            para_lines=[]; j=i; setext_level=None
            while j < len(lines):
                l=lines[j]
                if l.strip()=='':
                    break
                if j>i:
                    # setext
                    if re.match(r'^ {0,3}=+[ \t]*$', l): setext_level=1; j+=1; break
                    if re.match(r'^ {0,3}-+[ \t]*$', l): setext_level=2; j+=1; break
                    # description list marker if para is term (single para)
                    if self.ext("description_lists") and re.match(r'^ {0,3}:[ \t]+', l):
                        break
                    if self._is_block_start(l):
                        break
                    # table start within paragraph? comrak tables don't interrupt paragraph (they are para) - header line is para line itself
                para_lines.append(l); j+=1
            if setext_level is not None:
                content='\n'.join(para_lines).strip()
                out.append(self._render_heading(setext_level, content)); i=j; continue
            # description list handling: following lines starting :
            if self.ext("description_lists"):
                k=j; defs=[]
                while k < len(lines) and re.match(r'^ {0,3}:[ \t]+', lines[k]):
                    def_content=re.sub(r'^ {0,3}:[ \t]+','',lines[k]); defs.append(def_content); k+=1
                    # continuation lines indented? simple: lines that are indented and not blank
                    # not handling multi-para defs
                if defs:
                    # terms: each para line is a term (comrak may have multiple terms if multiple lines? treat each line as dt)
                    html='<dl>\n'
                    for term in para_lines:
                        html+=f'<dt>{self._inline(term.strip())}</dt>\n'
                    for d in defs:
                        html+=f'<dd>{self._inline(d.strip())}</dd>\n'
                    html+='</dl>\n'; out.append(html); i=k; continue
            # paragraph
            ptext='\n'.join(para_lines)
            if tight:
                out.append(self._inline(ptext)+'\n')
            else:
                out.append(f'<p>{self._inline(ptext)}</p>\n')
            i=j
        return ''.join(out)

    def _render_heading(self, level, content_raw):
        inline=self._inline(content_raw.strip())
        plain=striptags(inline).strip()
        slug=slugify(plain)
        # duplicate handling: comrak? If duplicate headings, anchor ids repeat? Keep track suffix maybe -1? We'll keep same for now, but headings list needs distinct? comrak header anchor insertion by marmite probably slugifies and if duplicates, same id. Check later.
        if slug in self.heading_slugs:
            self.heading_slugs[slug]+=1
            # marmite postprocess may keep same slug - don't suffix
        else:
            self.heading_slugs[slug]=1
        self.headings.append((level, plain, slug))
        return f'<h{level}><a href="#{slug}" aria-hidden="true" class="anchor" id="{slug}"></a>{inline}</h{level}>\n'

    def _is_thematic(self,line):
        s=line.strip()
        if len(s)<3: return False
        # remove spaces
        t=s.replace(' ','').replace('\t','')
        return bool(re.fullmatch(r'(\*{3,}|-{3,}|_{3,})', t))

    def _try_html_block(self, lines, i):
        line=lines[i]
        stripped=line.lstrip()
        if not stripped.startswith('<'): return None,0
        # comment
        if stripped.startswith('<!--'):
            buf=[]; j=i
            while j < len(lines):
                buf.append(lines[j])
                if '-->' in lines[j]: j+=1; break
                j+=1
            raw='\n'.join(buf)+'\n'
            if not self.render_opt("unsafe"): return '<!-- raw HTML omitted -->\n', j-i
            return raw, j-i
        # script/pre/style/textarea
        m=re.match(r'<(script|pre|style|textarea)[\s>]', stripped, re.I)
        if m:
            tag=m.group(1).lower(); buf=[]; j=i
            while j < len(lines):
                buf.append(lines[j]); j+=1
                if f'</{tag}>' in lines[j-1].lower(): break
            raw='\n'.join(buf)+'\n'
            if not self.render_opt("unsafe"): return '<!-- raw HTML omitted -->\n', j-i
            return raw, j-i
        # block tags type 6
        block_tags={'address','article','aside','base','basefont','blockquote','body','caption','center','col','colgroup','dd','details','dialog','dir','div','dl','dt','fieldset','figcaption','figure','footer','form','frame','frameset','h1','h2','h3','h4','h5','h6','head','header','hr','html','iframe','legend','li','link','main','menu','menuitem','nav','noframes','ol','optgroup','option','p','param','section','source','summary','table','tbody','td','tfoot','th','thead','title','tr','track','ul'}
        m=re.match(r'</?([A-Za-z][A-Za-z0-9-]*)(?:[\s>/])', stripped)
        if m and m.group(1).lower() in block_tags:
            buf=[]; j=i
            while j < len(lines) and lines[j].strip()!='':
                buf.append(lines[j]); j+=1
            raw='\n'.join(buf)+'\n'
            if not self.render_opt("unsafe"): return '<!-- raw HTML omitted -->\n', j-i
            return raw, j-i
        # other html block type 7 if line is single tag alone
        if re.match(r'^</?[A-Za-z][^>]*>[ \t]*$', stripped):
            # only if not interrupting paragraph (this is block start so ok)
            buf=[]; j=i
            while j < len(lines) and lines[j].strip()!='':
                buf.append(lines[j]); j+=1
            raw='\n'.join(buf)+'\n'
            if not self.render_opt("unsafe"): return '<!-- raw HTML omitted -->\n', j-i
            return raw, j-i
        return None,0

    def _is_block_start(self,line):
        if re.match(r'^ {0,3}(#{1,6})[ \t]', line): return True
        if re.match(r'^( {0,3})(`{3,}|~{3,})', line): return True
        if re.match(r'^ {0,3}>[ \t]?', line): return True
        if self._is_list_start(line): return True
        if self._is_thematic(line): return True
        stripped=line.lstrip()
        if stripped.startswith('<') and self._try_html_block([line],0)[0] is not None: return True
        return False

    # ---- list ----
    def _list_marker(self,line):
        m=re.match(r'^( *)([-+*]|\d{1,9}[.)])([ \t]+)(.*)$', line)
        if not m: return None
        indent=len(m.group(1)); marker=m.group(2); spaces=m.group(3); rest=m.group(4)
        ordered=marker[-1] in '.)' and marker[:-1].isdigit()
        start=int(marker[:-1]) if ordered else None
        marker_type=marker[-1] if ordered else marker
        # content indent: indent + len(marker)+ spaces (if spaces >4 treat as 1)
        sp=len(spaces.expandtabs())
        if sp>4: sp=1
        content_indent=indent+len(marker)+sp
        return {'indent':indent,'marker':marker,'ordered':ordered,'start':start,'delim':marker_type,'bul_char':marker if not ordered else None,'content_indent':content_indent,'rest':rest}

    def _is_list_start(self,line):
        return self._list_marker(line) is not None

    def _parse_list(self,lines,i):
        first=self._list_marker(lines[i]); ordered=first['ordered']; indent=first['indent']
        items=[]; j=i; loose=False
        while j < len(lines):
            line=lines[j]
            if line.strip()=='':
                # blank within list: peek ahead
                # look forward to see if next nonblank is continuation or next item; blank indicates possible loose
                k=j+1
                while k < len(lines) and lines[k].strip()=='': k+=1
                if k>=len(lines): j=k; break
                nm=self._list_marker(lines[k])
                if nm and nm['indent']==indent and self._same_list(first,nm):
                    loose=True; j=k; 
                    # will parse next item in next loop iteration
                    break_marker=True
                    # consume blank lines; item loop will handle
                    # To avoid infinite, set a flag by advancing j to k and continuing outer while expecting marker
                    # We'll handle by falling through to marker parsing below using j=k
                    # Use a marker parse at top of loop
                    # implement by setting j=k and continuing to marker check
                    # marker check is below at loop start (we restructure)
                    # Instead handle here:
                    # parse next item starting at k in next iteration via flag
                    # break out of blank handling into loop head (which checks marker)
                    # So set j=k and continue
                    j=k
                    # check if next loop will parse marker (loop head needs to accept)
                    # We'll proceed to marker logic in same iteration by not continuing python while? Simpler: goto via flag
                    # Use recursion? We'll just continue loop; loop top currently doesn't parse marker, so we need code after blank handling to parse.
                    # To make this work, we jump to parsing below by setting a variable
                    # We'll set line = lines[j] and fall through
                    if j < len(lines):
                        line=lines[j]
                    else:
                        break
                elif lines[k].startswith(' '*(first['content_indent'])) or lines[k].startswith('\t'):
                    loose=True; 
                    # blank is part of current item; add marker in item lines and advance
                    items[-1].append('')
                    j+=1; continue
                else:
                    # list ends
                    j+=1; break
            m=self._list_marker(line) if j < len(lines) else None
            if m and m['indent']==indent and self._same_list(first,m):
                items.append([m['rest']]); j+=1; continue
            # continuation line of current item
            if items:
                # indented continuation
                if line.startswith(' '*(first['content_indent'])):
                    items[-1].append(line[first['content_indent']:]); j+=1; continue
                if line.startswith('\t'):
                    items[-1].append(line[1:]); j+=1; continue
                if line.strip()=='':
                    items[-1].append(''); j+=1; continue
                # lazy continuation if it's paragraph text and previous item not blank ended
                # if it's a block start at same indent, list ends
                if self._is_block_start(line) and not self._is_list_start(line):
                    break
                # lazy line
                items[-1].append(line.strip()); j+=1; continue
            break
        # if blank handling fell through weird, safety
        # detect loose also if any item contains blank line separating blocks (internal blank not at end)
        for it in items:
            # remove trailing blanks
            while it and it[-1]=='': it.pop()
            if '' in it: loose=True
        tag='ol' if ordered else 'ul'
        start_attr=''
        if ordered and first['start'] not in (None,1): start_attr=f' start="{first["start"]}"'
        html=f'<{tag}{start_attr}>\n'
        for it in items:
            # tasklist check on first line
            task=None; 
            if it:
                tm=re.match(r'^\[([ xX])\][ \t]+(.*)$', it[0])
                if tm and self.ext("tasklist"):
                    task=(tm.group(1).lower()=='x'); it[0]=tm.group(2)
            inner=self._parse_blocks(it, tight=not loose)
            if not loose:
                # tight: strip <p> wrappers at top level
                inner=re.sub(r'<p>(.*?)</p>\n', lambda mm: mm.group(1)+'\n', inner, flags=re.S)
            inner_stripped=inner.rstrip('\n')
            if task is not None:
                checked=' checked=""' if task else ''
                checkbox=f'<input type="checkbox"{checked} disabled="" /> '
                if loose:
                    # checkbox inside first p? comrak: <li><p><input...>?? approx place after <p> if present
                    if inner_stripped.startswith('<p>'):
                        inner_stripped='<p>'+checkbox+inner_stripped[3:]
                    else:
                        inner_stripped=checkbox+inner_stripped
                    html+=f'<li>\n{inner_stripped}\n</li>\n'
                else:
                    html+=f'<li>{checkbox}{inner_stripped}</li>\n'
            else:
                if loose:
                    html+=f'<li>\n{inner_stripped}\n</li>\n'
                else:
                    # comrak: if inner contains block elements starting after first line, format <li>text\n<ul>...
                    # Our inner_stripped already: first line text then \n<...> handling: when inner has multiple blocks, comrak puts <li>first...
                    # If inner_stripped contains '\n<', keep as is starting directly
                    html+=f'<li>{inner_stripped}</li>\n'
        html+=f'</{tag}>\n'
        return html, j-i

    def _same_list(self, first, other):
        if first['ordered']!=other['ordered']: return False
        if first['ordered']: return first['delim']==other['delim']
        return first['bul_char']==other['bul_char']

    # ---- table ----
    def _split_row(self,line):
        s=line.strip()
        if s.startswith('|'): s=s[1:]
        if s.endswith('|') and not s.endswith('\\|'): s=s[:-1]
        cells=[]; cur=''; i=0; in_code=False
        while i < len(s):
            ch=s[i]
            if ch=='\\' and i+1<len(s) and s[i+1]=='|': cur+='|'; i+=2; continue
            if ch=='`': in_code=not in_code; cur+=ch; i+=1; continue
            if ch=='|' and not in_code: cells.append(cur.strip()); cur=''; i+=1; continue
            cur+=ch; i+=1
        cells.append(cur.strip()); return cells

    def _is_table_delim(self,line):
        if '-' not in line: return False
        cells=self._split_row(line)
        return all(re.fullmatch(r':?-+:?', c.strip()) for c in cells if c.strip()!='') and len(cells)>0 and all(c.strip() for c in cells)

    def _parse_table(self,lines,i):
        header=self._split_row(lines[i]); delims=self._split_row(lines[i+1]); aligns=[]
        for d in delims:
            d=d.strip()
            if d.startswith(':') and d.endswith(':'): aligns.append('center')
            elif d.endswith(':'): aligns.append('right')
            elif d.startswith(':'): aligns.append('left')
            else: aligns.append(None)
        ncol=len(header)
        html='<table>\n<thead>\n<tr>\n'
        for idx,cell in enumerate(header):
            a=f' align="{aligns[idx]}"' if idx<len(aligns) and aligns[idx] else ''
            html+=f'<th{a}>{self._inline(cell)}</th>\n'
        html+='</tr>\n</thead>\n<tbody>\n'
        j=i+2; rows=[]
        while j < len(lines) and lines[j].strip()!='' and '|' in lines[j]:
            rows.append(self._split_row(lines[j])); j+=1
        for row in rows:
            html+='<tr>\n'
            for idx in range(ncol):
                cell=row[idx] if idx<len(row) else ''
                a=f' align="{aligns[idx]}"' if idx<len(aligns) and aligns[idx] else ''
                html+=f'<td{a}>{self._inline(cell)}</td>\n'
            html+='</tr>\n'
        html+='</tbody>\n</table>\n'
        return html,j-i

    def _try_alert(self, qlines, inner_html):
        # find first non-empty line
        for idx,l in enumerate(qlines):
            if l.strip()=='' : continue
            m=re.match(r'^\[!([A-Za-z]+)\][ \t]*(.*)$', l.strip())
            if not m: return None
            typ=m.group(1).lower()
            if typ not in ('note','tip','important','warning','caution'): return None
