                m=re.match(r'<([A-Za-z][A-Za-z0-9+.-]{1,31}:[^<>\s]+)>', s[i:])
                if m:
                    url=m.group(1); out.append(f'<a href="{escape_attr(url)}">{escape_html_text(url)}</a>'); i+=len(m.group(0)); continue
                m=re.match(r'<([A-Za-z0-9.!#$%&\'*+/=?^_`{|}~-]+@[A-Za-z0-9.-]+\.[A-Za-z]+)>', s[i:])
                if m:
                    email=m.group(1); out.append(f'<a href="mailto:{escape_attr(email)}">{escape_html_text(email)}</a>'); i+=len(m.group(0)); continue
                m=re.match(r'</?[A-Za-z][A-Za-z0-9-]*(?:\s[^<>]*)?/?>', s[i:])
                if m:
                    raw=m.group(0)
                    if not self.render_opt("unsafe"):
                        out.append('<!-- raw HTML omitted -->')
                    elif self.ext("tagfilter") and re.match(r'</?(title|textarea|style|xmp|iframe|noembed|noframes|script|plaintext)[\s>]', raw, re.I):
                        out.append(raw.replace('<','&lt;',1))
                    else:
                        out.append(raw)
                    i+=len(raw); continue
                m=re.match(r'<[!?][^>]*>', s[i:])
                if m:
                    raw=m.group(0); out.append(raw if self.render_opt("unsafe") else '<!-- raw HTML omitted -->'); i+=len(raw); continue
                out.append('&lt;'); i+=1; continue
            # wikilinks
            if ch=='[' and self._wikilinks_enabled() and i+1<n and s[i+1]=='[':
                end=s.find(']]', i+2)
                if end!=-1:
                    inner=s[i+2:end]
                    out.append(self._render_wikilink(inner)); i=end+2; continue
            # footnote ref
            if ch=='[' and self.ext("footnotes") and i+1<n and s[i+1]=='^':
                m=re.match(r'\[\^([^\]]+)\]', s[i:])
                if m:
                    label=m.group(1)
                    if label in self.footnote_defs:
                        if label not in self.footnote_order: self.footnote_order.append(label)
                        idx=self.footnote_order.index(label)+1
                        count=self.footnote_ref_counts.get(label,0)+1; self.footnote_ref_counts[label]=count
                        ref_id=f'fnref-{idx}' if count==1 else f'fnref-{idx}-{count}'
                        out.append(f'<sup class="footnote-ref"><a href="#fn-{idx}" id="{ref_id}" data-footnote-ref>{idx}</a></sup>'); i+=len(m.group(0)); continue
                    else:
