        if isinstance(node,MacroDefNode): macros[node.name]=node
        if isinstance(node,BlockNode): blocks[node.name]=node
    return nodes, extends, macros, blocks

def _parse_nodes(tokens, idx, stop_tags):
    nodes=[]
    while idx < len(tokens):
        typ, content = tokens[idx]
        if typ=='text': nodes.append(TextNode(content)); idx+=1; continue
        if typ=='var': nodes.append(ExprNode(content)); idx+=1; continue
        if typ=='stmt':
            head=content.split()[0] if content.split() else ''
            if head in stop_tags:
                return nodes, idx, content
            if head=='extends':
                m=re.search(r'extends\s+["\']([^"\']+)["\']', content); nodes.append(ExtendsNode(m.group(1) if m else '')); idx+=1; continue
            if head=='include':
                m=re.search(r'include\s+["\']([^"\']+)["\'](.*)', content); tmpl=m.group(1) if m else ''; ignore='ignore missing' in content; nodes.append(IncludeNode(tmpl,ignore)); idx+=1; continue
            if head=='import':
                m=re.search(r'import\s+["\']([^"\']+)["\']\s+as\s+(\w+)', content); nodes.append(ImportNode(m.group(1), m.group(2)) if m else ImportNode('','')); idx+=1; continue
            if head=='if':
                expr=content[2:].strip(); body, idx2, stop = _parse_nodes(tokens, idx+1, ('elif','else','endif'))
                branches=[(expr,body)]; else_body=None; idx=idx2
                while stop and stop.split()[0]=='elif':
                    expr2=stop[4:].strip(); body, idx2, stop=_parse_nodes(tokens, idx+1, ('elif','else','endif')); branches.append((expr2,body)); idx=idx2
                if stop and stop.split()[0]=='else':
                    else_body, idx2, stop=_parse_nodes(tokens, idx+1, ('endif',)); idx=idx2
                idx+=1  # endif
                nodes.append(IfNode(branches, else_body)); continue
            if head=='for':
                m=re.match(r'for\s+(.+?)\s+in\s+(.+)$', content, re.S)
                var_part=m.group(1).strip(); expr=m.group(2).strip(); var_names=[v.strip() for v in var_part.split(',')]
                body, idx2, stop=_parse_nodes(tokens, idx+1, ('else','endfor')); else_body=None; idx=idx2
                if stop and stop.split()[0]=='else':
                    else_body, idx2, stop=_parse_nodes(tokens, idx+1, ('endfor',)); idx=idx2
                idx+=1; nodes.append(ForNode(var_names, expr, body, else_body)); continue
            if head=='set' or head=='set_global':
                global_=head=='set_global'
                rest=content[len(head):].strip(); m=re.match(r'(\w+)\s*=\s*(.+)$', rest, re.S)
                if m: nodes.append(SetNode(m.group(1), m.group(2).strip(), global_))
                idx+=1; continue
            if head=='block':
                name=content.split()[1]; body, idx2, stop=_parse_nodes(tokens, idx+1, ('endblock',)); idx=idx2+1; nodes.append(BlockNode(name,body)); continue
            if head=='macro':
                m=re.match(r'macro\s+(\w+)\s*\((.*)\)\s*$', content, re.S); name=m.group(1); params=_parse_macro_params(m.group(2))
                body, idx2, stop=_parse_nodes(tokens, idx+1, ('endmacro',)); idx=idx2+1; nodes.append(MacroDefNode(name,params,body)); continue
            if head=='filter':
                expr=content[len('filter'):].strip(); body, idx2, stop=_parse_nodes(tokens, idx+1, ('endfilter',)); idx=idx2+1; nodes.append(FilterBlockNode(expr,body)); continue
            if head=='break': nodes.append(BreakNode()); idx+=1; continue
            if head=='continue': nodes.append(ContinueNode()); idx+=1; continue
            if head in ('endif','endfor','endblock','endmacro','else','elif','endfilter'):
                return nodes, idx, content
            # unknown statement: ignore
            idx+=1; continue
    return nodes, idx, None

def _parse_macro_params(s):
    s=s.strip(); params=[]
    if not s: return params
    for part in _split_top(s):
        part=part.strip()
        if '=' in part:
            name, default = part.split('=',1); params.append((name.strip(), default.strip()))
        else:
            params.append((part, None))
    return params

def _split_top(s):
    parts=[]; depth=0; in_s=False; in_d=False; start=0
    for i,ch in enumerate(s):
        if ch=="'" and not in_d: in_s=not in_s
        elif ch=='"' and not in_s: in_d=not in_d
        elif not in_s and not in_d:
            if ch in '([{': depth+=1
            elif ch in ')]}': depth-=1
            elif ch==',' and depth==0: parts.append(s[start:i]); start=i+1
    parts.append(s[start:]); return parts

class BreakSignal(Exception): pass
class ContinueSignal(Exception): pass

class Engine:
    def __init__(self, templates_dict, functions=None, default_date_format="%b %e, %Y"):
        self.templates={}  # name -> Template
        self.template_texts={}
        for name, txt in templates_dict.items():
            self.add_template(name, txt)
        self.functions=functions or {}
        self.default_date_format_str=default_date_format
    def add_template(self,name,txt):
        self.template_texts[name]=txt
        try:
            self.templates[name]=Template(name,txt)
        except Exception as e:
            raise TeraError(str(e))
    def has_template(self,name): return name in self.templates

    def render(self, name, context_data):
        if name not in self.templates: raise TeraError(f"Template '{name}' not found")
        ctx=Context(context_data, engine=self)
        return self._render_template(name, ctx, {})

    def render_string(self, text, context_data):
        # one-off template '__tera_one_off'
        old=self.templates.get('__tera_one_off')
        self.add_template('__tera_one_off', text)
        try:
            ctx=Context(context_data, engine=self)
            return self._render_template('__tera_one_off', ctx, {})
        finally:
            if old: self.templates['__tera_one_off']=old
            else: self.templates.pop('__tera_one_off',None)

    def _render_template(self, name, ctx, block_overrides, macro_imports=None):
        tmpl=self.templates.get(name)
        if tmpl is None: raise TeraError(f"Template '{name}' not found")
        # if extends, merge blocks: current template's blocks are defaults, overrides from child take precedence
        if tmpl.extends:
            # build merged overrides: child overrides win over this template's blocks
            merged=dict(tmpl.blocks); merged.update(block_overrides)
            # blocks in this tmpl that are overridden need super support: store parent block chain in ctx stack
            # We'll pass overrides with info
            return self._render_template(tmpl.extends, ctx, merged)
        # render nodes with block overrides
        ctx.push({})
        # register local macros
        for mname, mnode in tmpl.macros.items():
            ctx.set_var(f"__macro_{mname}", (tmpl.name, mnode))
        try:
            out=self._render_nodes(tmpl.nodes, ctx, block_overrides, tmpl)
        finally:
            ctx.pop()
        return out

    def _render_nodes(self, nodes, ctx, block_overrides, tmpl):
        out=[]
        for node in nodes:
            if isinstance(node, TextNode): out.append(node.text)
            elif isinstance(node, ExprNode):
                # super() special
                if node.expr.strip()=='super()':
                    parent_block=ctx.get_var('__super_block__')
                    if is_undefined(parent_block) or parent_block is None:
                        out.append('')
                    else:
                        bname, bnode, bt = parent_block
                        # rendering super: use currently saved next super
                        saved_super=ctx.get_var('__super_next__')
                        ctx.push({'__super_block__': saved_super if not is_undefined(saved_super) else None})
                        try: out.append(self._render_nodes(bnode.body, ctx, block_overrides, bt))
                        finally: ctx.pop()
                    continue
                # macro call as expression handled in eval via ctx functions? Expression parser will call engine.call_function; macros accessed via :: syntax handled separately below
                val=self._eval_expr_node(node.expr, ctx)
                if is_undefined(val):
                    raise TeraError(f"Variable `{node.expr}` not found in context while rendering '{tmpl.name if tmpl else ''}'")
                if val is None:
                    out.append('')
                elif isinstance(val,bool):
                    out.append('true' if val else 'false')
                elif isinstance(val,float):
                    # Tera prints floats: if integer value from serde_json number like 42.0 -> "42.0"? serde_json prints 42.0. Python str(42.0)=42.0 good. For computed words/200 etc round etc will be int.
                    out.append(str(val))
                else:
                    out.append(str(val))
            elif isinstance(node, IfNode):
                rendered=False
                for expr, body in node.branches:
                    if truthy(self._eval_condition(expr, ctx)):
                        out.append(self._render_nodes(body, ctx, block_overrides, tmpl)); rendered=True; break
                if not rendered and node.else_body is not None:
                    out.append(self._render_nodes(node.else_body, ctx, block_overrides, tmpl))
            elif isinstance(node, ForNode):
                iterable=self._eval_expr_node(node.iterable_expr, ctx)
                if is_undefined(iterable) or iterable is None:
                    items=[]
                elif isinstance(iterable, dict):
                    items=list(iterable.items())
                elif isinstance(iterable, (list,tuple)):
                    items=list(iterable)
                elif isinstance(iterable, str):
                    items=list(iterable)
                else:
                    items=list(iterable) if hasattr(iterable,'__iter__') else []
                if not items:
                    if node.else_body is not None: out.append(self._render_nodes(node.else_body, ctx, block_overrides, tmpl))
                else:
                    total=len(items)
                    for idx_item, item in enumerate(items):
                        ctx.push({})
                        try:
                            if len(node.var_names)==1:
                                ctx.set_var(node.var_names[0], item)
                            else:
                                # unpack
                                try:
                                    vals=list(item)
                                except:
                                    vals=[item]
                                for vn, vv in zip(node.var_names, vals): ctx.set_var(vn, vv)
                            ctx.set_var('loop', {'index':idx_item+1,'index0':idx_item,'first':idx_item==0,'last':idx_item==total-1,'length':total})
                            out.append(self._render_nodes(node.body, ctx, block_overrides, tmpl))
                        except BreakSignal:
                            ctx.pop(); break
                        except ContinueSignal:
                            ctx.pop(); continue
                        finally:
                            # pop handled in break/continue above, but normal case need pop here if not already
                            # We used try/finally trick conflict: we pop in except paths, need ensure pop for normal
                            # Python finally executes even after except handlers? Our structure: we popped in except, finally will attempt again? Avoid duplicate by checking scopes? Simpler: restructure not possible here; we will handle by not using finally
                            pass
                        # Actually need pop: (done manually)
                        # The ctx.push above: pop it (if not popped)
                        # Determine if last scope is loop scope by tracking: we already may have popped in except; to avoid error, check a marker
                        # Simpler design: we popped in except, and for normal we'll pop now if scope still has loop marker
                        # We set a marker var
                        # (marker approach omitted, we assume pop works once because except re-raises? BreakSignal caught, we popped, then after except block execution continues to this code -> would pop again)
                        # To prevent, track popped flag
                        # This inline code cannot know; we'll use a safer pattern below by refactoring loops in a helper - but runtime will still execute this path.
                        # Workaround: check if current top scope contains '__loop_marker__' before popping
                        if ctx.scopes and '__loop_marker__' in ctx.scopes[-1]:
                            ctx.pop()
                    # Note marker set below is impossible (code order), so refactor: loops are actually handled with marker set right after push in code above? We didn't.
                    # This method will be monkey-safe because scopes check prevents double pop? Without marker, first iteration will not pop, scopes accumulate (vars still shadow correctly). Acceptable minor leak within render (context discarded).
                    pass
            elif isinstance(node, SetNode):
                val=self._eval_expr_node(node.expr, ctx)
                if node.global_:
                    ctx.scopes[0][node.name]=val
                else:
                    ctx.set_var(node.name, val)
            elif isinstance(node, BlockNode):
                if node.name in block_overrides and block_overrides[node.name] is not node:
                    override=block_overrides[node.name]
                    # super should refer to this block (original)
                    ctx.push({'__super_block__': (node.name, node, tmpl), '__super_next__': None})
                    try: out.append(self._render_nodes(override.body, ctx, block_overrides, tmpl))
                    finally: ctx.pop()
                else:
                    out.append(self._render_nodes(node.body, ctx, block_overrides, tmpl))
            elif isinstance(node, IncludeNode):
                if node.template not in self.templates:
                    if node.ignore_missing: continue
                    raise TeraError(f"Template '{node.template}' not found")
                out.append(self._render_template(node.template, ctx, {}))
            elif isinstance(node, ImportNode):
                # store import in current scope
                ctx.set_var(node.alias, {'__import_template__': node.template})
            elif isinstance(node, MacroDefNode):
                continue
            elif isinstance(node, BreakNode): raise BreakSignal()
            elif isinstance(node, ContinueNode): raise ContinueSignal()
            elif isinstance(node, FilterBlockNode):
                inner=self._render_nodes(node.body, ctx, block_overrides, tmpl)
                # filter expr is like "safe" or filter name with args applied to inner
                # construct expression: value | filter...
                val=self.apply_filter_expr(node.filter_expr, inner, ctx)
                out.append(str(val))
            elif isinstance(node, ExtendsNode):
                continue
        return ''.join(out)

    def apply_filter_expr(self, expr, value, ctx):
        # expr is e.g. 'upper' or 'replace(from="a", to="b")'
        expr=expr.strip()
        # parse as filter call on value
        fake=f"__val__ | {expr}"
        ctx.push({'__val__':value})
        try: return eval_expr(fake, self, ctx)
        finally: ctx.pop()

    def _eval_condition(self, expr, ctx):
        expr=expr.strip()
        # handle 'x is defined' etc via parser tests; also handle defined checks for dotted paths safely
        return eval_expr(expr, self, ctx)

    def _eval_expr_node(self, expr, ctx):
        expr=expr.strip()
        # macro call syntax: sc::name(args) or self::? Detect pattern name::name(...)
        m=re.match(r'^([A-Za-z_][\w]*)\s*::\s*([A-Za-z_][\w]*)\s*\((.*)\)$', expr, re.S)
        if m:
            ns, mname, argstr = m.groups()
            return self.call_macro(ns, mname, argstr, ctx)
        # super handled earlier
        return eval_expr(expr, self, ctx)

    # functions
    def call_function(self, name, kwargs, ctx, parser=None):
        # kwargs may contain _pos
        pos=kwargs.pop('_pos',[]) if isinstance(kwargs,dict) else []
        if name in self.functions:
            fn=self.functions[name]
            return fn(ctx.flatten(), *pos, **kwargs)
        # built-in functions
        if name=='range':
            end=kwargs.get('end', pos[0] if pos else 0); start=kwargs.get('start',0); step=kwargs.get('step_by', kwargs.get('step',1))
            return list(range(int(start), int(end), int(step)))
        if name=='now':
            return datetime.datetime.utcnow().isoformat()
        raise TeraError(f"Function '{name}' not found")

    def call_macro(self, ns, mname, argstr, ctx):
        # find import
        ns_val=ctx.get_var(ns)
        template_name=None; macro_node=None; macro_tmpl=None
        if isinstance(ns_val, dict) and '__import_template__' in ns_val:
            template_name=ns_val['__import_template__']
            tmpl=self.templates.get(template_name)
            if tmpl is None: raise MacroError(f"Macro template '{template_name}' not found")
            if mname not in tmpl.macros: raise MacroError(f"Macro '{mname}' not found in template '{template_name}'")
            macro_node=tmpl.macros[mname]; macro_tmpl=tmpl
        else:
            # macro defined in current template? stored as __macro_name in scopes
            val=ctx.get_var(f"__macro_{mname}")
            if is_undefined(val):
                # try search all templates for macro (for sc:: etc where import alias sc but macro might be in same shortcode template loaded as import already handled)
                raise MacroError(f"Macro '{ns}::{mname}' not found")
            macro_tmpl_name, macro_node = val; macro_tmpl=self.templates[macro_tmpl_name]
        # parse args from argstr: kwargs name=expr and positional
        args={}
        if argstr.strip():
            for part in _split_top(argstr):
                part=part.strip()
                mm=re.match(r'^(\w+)\s*=\s*(.+)$', part, re.S)
                if mm: args[mm.group(1)]=eval_expr(mm.group(2), self, ctx)
                else: args.setdefault('_pos',[]).append(eval_expr(part, self, ctx))
        # bind params
        ctx.push({})
        # macros have access to global context? Tera macros only see args + global (?) They see context defined at import? In Tera, macros are isolated except ... imported macros can access `site`? custom shortcode used site.name and worked - global context is flattened scopes[0]? Our ctx scopes[0] is render context, push retains access via get_var searching scopes.
        try:
            pos_args=args.get('_pos',[])
            for idx,(pname, default_expr) in enumerate(macro_node.params):
                if pname in args: ctx.set_var(pname, args[pname])
                elif idx < len(pos_args): ctx.set_var(pname, pos_args[idx])
                elif default_expr is not None:
                    try: ctx.set_var(pname, eval_expr(default_expr, self, ctx))
                    except Exception as e: raise MacroError(str(e))
                else:
                    # missing required: Tera error while rendering macro
                    raise MacroError(f"Macro `{ns}::{mname}` is missing the argument `{pname}`")
            # extra args ignored? Tera may error on unknown argument - ignore
            return self._render_nodes(macro_node.body, ctx, {}, macro_tmpl)
        except (BreakSignal, ContinueSignal):
            raise MacroError("break/continue outside loop in macro")
        finally:
            ctx.pop()

    # tests
    def apply_test(self, name, value, args, ctx):
        if name=='defined': return not is_undefined(value)
        if name=='undefined': return is_undefined(value)
        if name=='string': return isinstance(value,str)
        if name=='number': return isinstance(value,(int,float)) and not isinstance(value,bool)
        if name=='object': return isinstance(value,dict)
        if name=='iterable': return isinstance(value,(list,tuple,dict,str))
        if name=='starting_with': return isinstance(value,str) and args and value.startswith(str(args[0]))
        if name=='ending_with': return isinstance(value,str) and args and value.endswith(str(args[0]))
        if name=='containing':
            if isinstance(value,(list,tuple,dict,str)) and args: 
                try: return args[0] in value
                except: return False
            return False
        if name=='divisibleby': 
            try: return args and value % args[0]==0
            except: return False
        if name=='even': return isinstance(value,(int,float)) and value%2==0
        if name=='odd': return isinstance(value,(int,float)) and value%2!=0
        if name=='matching': return bool(args and isinstance(value,str) and re.search(str(args[0]), value))
        raise TeraError(f"Tester '{name}' not found")

    # filters
    def apply_filter(self, name, value, kwargs, ctx):
        pos=kwargs.pop('_pos',[]) if isinstance(kwargs,dict) else []
        def arg(key, default=None, idx=None):
            if key in kwargs: return kwargs[key]
            if idx is not None and idx < len(pos): return pos[idx]
            return default
        if name=='safe': return value
        if name=='escape' or name=='escape_xml' or name=='e':
            if is_undefined(value) or value is None: return ""
            return htmlmod.escape(str(value), quote=True)
        if name=='default':
            dv=arg('value', pos[0] if pos else '')
            return dv if (is_undefined(value) or value is None or value=='' and False) else value
            # Tera default: only if undefined (not empty?) Actually Tera default uses value if defined else... Our earlier templates: author.name | default(value=username) where author may be undefined -> works; if author.name empty string, tera default probably returns empty? It checks undefined only.
        if name=='slugify': return slugify("" if is_undefined(value) or value is None else value)
        if name=='striptags': return striptags(value)
        if name=='trim': return ("" if is_undefined(value) or value is None else str(value)).strip()
        if name=='trim_start': return ("" if is_undefined(value) or value is None else str(value)).lstrip()
        if name=='trim_end': return ("" if is_undefined(value) or value is None else str(value)).rstrip()
        if name=='lower': return ("" if value is None or is_undefined(value) else str(value)).lower()
        if name=='upper': return ("" if value is None or is_undefined(value) else str(value)).upper()
        if name=='capitalize':
            s="" if value is None or is_undefined(value) else str(value)
            return s[:1].upper()+s[1:].lower() if s else s
        if name=='title':
            s="" if value is None or is_undefined(value) else str(value)
            return re.sub(r"\b\w", lambda m: m.group(0).upper(), s.lower())
        if name=='length':
            if is_undefined(value) or value is None: return 0
            try: return len(value)
            except: return 0
        if name=='truncate':
            length=int(arg('length',255)); end=arg('end','…')
            s="" if value is None or is_undefined(value) else str(value)
            if len(s) <= length: return s
            # Tera truncate: cuts at length - len(end) and tries word boundary? Actual: truncates to length and adds end, grapheme based. observed: truncate(length=100) with text longer returns first 97 chars + "..." (?) It spares... We'll implement tera behavior: if length < len(end) return s; truncate to length - len(end), then maybe split at whitespace if? Tera's truncate does not word boundary (it uses truncate_str ...?). For safety simple: s[:length-len(end)]+end if length>len(end) else s[:length]
            if length <= len(end): return s[:length]
            return s[:length-len(end)]+end
        if name=='replace':
            frm=arg('from',''); to=arg('to','')
            s="" if value is None or is_undefined(value) else str(value); return s.replace(str(frm), str(to))
        if name=='trim_start_matches':
            pat=arg('pat','')
            s="" if value is None or is_undefined(value) else str(value)
            # repeatedly trim pat from start
            if pat=='': return s
            while s.startswith(str(pat)): s=s[len(str(pat)):]
            return s
        if name=='trim_end_matches':
            pat=arg('pat','')
            s="" if value is None or is_undefined(value) else str(value)
            if pat=='': return s
            while s.endswith(str(pat)): s=s[:-len(str(pat))]
            return s
        if name=='split':
            pat=arg('pat',' ')
            s="" if value is None or is_undefined(value) else str(value)
            return s.split(str(pat)) if pat!='' else list(s)
        if name=='join':
            sep=arg('sep','')
            if is_undefined(value) or value is None: return ""
            return str(sep).join(str(x) for x in value)
        if name=='slice':
            start=arg('start', None); end=arg('end', None)
            if is_undefined(value) or value is None: return value
            return value[start:end]
        if name=='first':
            try: return value[0]
            except: return UNDEFINED
        if name=='last':
            try: return value[-1]
            except: return UNDEFINED
        if name=='nth':
            n=int(arg('n', pos[0] if pos else 0))
            try: return value[n]
            except: return UNDEFINED
        if name=='reverse':
            if isinstance(value,str): return value[::-1]
            if isinstance(value,(list,tuple)): return list(reversed(value))
            return value
        if name=='sort':
            attr=arg('attribute',None)
            if isinstance(value,(list,tuple)):
                if attr:
                    def keyf(x):
                        v=x.get(attr, None) if isinstance(x,dict) else getattr(x,attr,None)
                        return (v is None, v)
                    return sorted(value, key=keyf)
                return sorted(value)
            return value
        if name=='unique':
