                if x not in seen: seen.append(x); out.append(x)
            return out
        if name=='map':
            attr=arg('attribute','')
            out=[]
            for x in value or []:
                out.append(x.get(attr, UNDEFINED) if isinstance(x,dict) else UNDEFINED)
