                        if isinstance(item,(list,tuple)): menu.append(list(item))
                        else: menu.append(item)
                    base[k]=menu
                elif k in ('authors','streams','series') and isinstance(v,dict):
                    base[k]=normalize_config_maps(k,v)
                else:
                    base[k]=v
            # unknown ignored
    LOG.info("marmite::site", f"Config loaded from: {config_path_str}")
    return base, config_path_str, raw, text

def normalize_config_maps(kind, v):
    out={}
    for key,val in v.items():
        if kind=='authors' and isinstance(val,dict):
            out[str(key)]={"name":val.get("name"),"avatar":val.get("avatar"),"bio":val.get("bio"),"links":val.get("links")}
            # links: convert tuples to lists
            if isinstance(out[str(key)]["links"], list):
                out[str(key)]["links"]=[list(x) if isinstance(x,(list,tuple)) else x for x in out[str(key)]["links"]]
        elif kind=='streams' and isinstance(val,dict):
            out[str(key)]={"display_name":val.get("display_name")}
        elif kind=='series' and isinstance(val,dict):
            out[str(key)]={"display_name":val.get("display_name"),"description":val.get("description")}
        else:
            out[str(key)]=val
    return out

def build_parser_options(v):
    import copy
    opts=copy.deepcopy(DEFAULT_PARSER_OPTIONS)
    for section in ("render","parse","extension"):
        if isinstance(v.get(section), dict):
            for kk,vv in v[section].items(): opts[section][kk]=vv
    # keep any extra sections? serde would ignore unknown
    return opts

def yaml_syntax_debug(text, ex):
    # Best effort for unbalanced flow sequence as in probes
    lines=text.splitlines()
    for idx,line in enumerate(lines,1):
        if '[' in line and ']' not in line:
            col=line.find('[')+2  # column 1-based of after [? observed: line "invalid: [yaml: bad" '[' at col10, context_mark column10
            # problem_mark next line col1
            return f'Error {{ kind: PARSER, problem: "did not find expected \',\' or \']\'", problem_mark: Mark {{ line: {idx+1}, column: 1 }}, context: "while parsing a flow sequence", context_mark: Mark {{ line: {idx}, column: {col-1} }} }}'
        if line.rstrip().endswith('['):
            return f'Error {{ kind: PARSER, problem: "did not find expected node content", problem_mark: Mark {{ line: {idx+1}, column: 1 }}, context: "while parsing a flow node", context_mark: Mark {{ line: {idx+1}, column: 1 }} }}'
    return f'Error {{ kind: PARSER, problem: "{str(ex)}", problem_mark: Mark {{ line: 1, column: 1 }}, context: "", context_mark: Mark {{ line: 1, column: 1 }} }}'

