# ---------- Logging ----------
class Logger:
    def __init__(self, level=1): # 1 warn,2 info,3 debug,4 trace
        self.level=level
        rlog=os.environ.get("RUST_LOG","")
        if rlog:
            # env_logger style: parse max level name or module filters - approximate global max
            levels={"error":1,"warn":1,"info":2,"debug":3,"trace":4,"off":0}
            found=[]
            for part in rlog.split(","):
                part=part.strip()
                if "=" in part: part=part.split("=")[-1]
                if part.lower() in levels: found.append(levels[part.lower()])
            if found: self.level=max(found)
    def _log(self,lvl,lvlname,target,msg):
        if self.level < lvl: return
        ts=datetime.datetime.utcnow().strftime("%Y-%m-%dT%H:%M:%SZ")
        # env_logger pads level to 5 chars
        sys.stderr.write(f"[{ts} {lvlname:<5} {target}] {msg}\n"); sys.stderr.flush()
    def error(self,target,msg): self._log(1,"ERROR",target,msg)
    def warn(self,target,msg): self._log(1,"WARN",target,msg)
    def info(self,target,msg): self._log(2,"INFO",target,msg)
    def debug(self,target,msg): self._log(3,"DEBUG",target,msg)
    def trace(self,target,msg): self._log(4,"TRACE",target,msg)

LOG=Logger(1)

def rust_os_error(e):
    # format Python OSError like Rust io::Error Debug
    kind_map={2:"NotFound",13:"PermissionDenied",17:"AlreadyExists",20:"NotADirectory",21:"IsADirectory",22:"InvalidInput",28:"StorageFull"}
    kind=kind_map.get(e.errno or 0, "Other")
    msg=e.strerror or str(e)
    return f'Os {{ code: {e.errno or 0}, kind: {kind}, message: "{msg}" }}'

# ---------- Assets ----------
class Assets:
    def __init__(self):
        self.files={}
        base=Path(__file__).resolve().parent/"assets"
        if base.is_dir():
            for p in base.rglob("*"):
                if p.is_file(): self.files[p.relative_to(base).as_posix()]=p.read_bytes()
        else:
            # zipapp: read from argv[0] zip
            try:
                zpath=Path(sys.argv[0])
                with zipfile.ZipFile(zpath) as z:
                    for name in z.namelist():
                        if name.startswith("assets/") and not name.endswith("/"):
                            self.files[name[len("assets/"):]]=z.read(name)
            except Exception:
                pass
    def get(self, rel): return self.files.get(rel)
    def list_prefix(self,prefix):
        return sorted([k for k in self.files if k.startswith(prefix)])

