# ---------- YAML serialization for config ----------
def yaml_scalar(v):
    if v is None: return "null"
    if v is True: return "true"
    if v is False: return "false"
    if isinstance(v,(int,float)) and not isinstance(v,bool): return str(v)
    s=str(v)
    if s=="": return "''"
    # needs quoting if would parse as bool/null/number or contains special leading chars or ': ' ' #' etc
    needs=False
    if s.lower() in ("true","false","null","~","yes","no","on","off"): needs=True
    if re.fullmatch(r'[-+]?\d+(\.\d+)?', s): needs=True
    if s[0] in "!&*?|>%@`\"'#,[]{}:- " : 
        # '-' only if followed space, ':' handled below
        if not (s[0]=='-' and len(s)>1 and s[1]!=' '): needs=True
        if s[0] in "\"'": needs=True
    if ': ' in s or s.endswith(':'): needs=True
    if ' #' in s: needs=True
    if '\n' in s: needs=True
    if s.strip()!=s: needs=True
    if needs:
        return "'"+s.replace("'","''")+"'"
    return s

def yaml_dump_config(cfg):
    lines=[]
    def dump_map(d, indent):
        for k,v in d.items():
            key=str(k)
            if isinstance(v,dict):
                if not v: lines.append(' '*indent+f"{key}: {{}}")
                else: lines.append(' '*indent+f"{key}:"); dump_map(v,indent+2)
            elif isinstance(v,list):
                if not v: lines.append(' '*indent+f"{key}: []")
                else:
                    lines.append(' '*indent+f"{key}:")
                    dump_list(v,indent)
            else:
                lines.append(' '*indent+f"{key}: {yaml_scalar(v)}")
    def dump_list(lst, indent):
        for item in lst:
            if isinstance(item,list):
                if not item: lines.append(' '*indent+"- []")
                else:
                    # nested list: first element on dash line
                    lines.append(' '*indent+f"- - {yaml_scalar(item[0])}" if not isinstance(item[0],(dict,list)) else ' '*indent+"- -")
                    if isinstance(item[0],(dict,list)): pass
                    for sub in item[1:]:
                        if isinstance(sub,dict): lines.append(' '*(indent+2)+"-"); dump_map(sub,indent+4)
                        elif isinstance(sub,list): lines.append(' '*(indent+2)+"- (nested)")
                        else: lines.append(' '*(indent+2)+f"- {yaml_scalar(sub)}")
            elif isinstance(item,dict):
                if not item: lines.append(' '*indent+"- {}")
                else:
                    # serde_yaml sequence of maps: first key on dash line - approximate for file_mapping etc in config generation (not in defaults)
                    first=True
                    for kk,vv in item.items():
                        if first: lines.append(' '*indent+f"- {kk}: {yaml_scalar(vv) if not isinstance(vv,(dict,list)) else ''}"); first=False
                        else: lines.append(' '*(indent+2)+f"{kk}: {yaml_scalar(vv) if not isinstance(vv,(dict,list)) else ''}")
            else:
                lines.append(' '*indent+f"- {yaml_scalar(item)}")
    dump_map(cfg,0)
    return "\n".join(lines)+"\n"

def generated_config_text(cfg):
    # cfg is generated-defaults based (language blank etc) but preserve field order
    return yaml_dump_config(cfg)

# ---------- Config loading/validation ----------
class SiteError(Exception): pass

def _value_col(text, key):
    # find line for key at top level, return (line, column of value) 1-based
    for idx,line in enumerate(text.splitlines(),1):
        m=re.match(rf'^\s*{re.escape(key)}\s*:\s*', line)
        if m: return idx, m.end()+1
    return 1,1

def validate_config(cfg_raw, cfg, text):
