        'streams_title':('string',str),'streams_content_title':('string',str),'series_title':('string',str),'series_content_title':('string',str),
        'default_author':('string',str),'authors_title':('string',str),'search_title':('string',str),'content_path':('string',str),'site_path':('string',str),
        'templates_path':('string',str),'static_path':('string',str),'media_path':('string',str),'card_image':('string',str),'banner_image':('string',str),'logo_image':('string',str),
        'default_date_format':('string',str),'gallery_path':('string',str),
    }
    for field,(exp,typ) in checks.items():
        if field in cfg_raw and cfg_raw[field] is not None and not isinstance(cfg_raw[field], typ):
            line,col=_value_col(text,field); raise SiteError(f'Failed to parse config YAML: Error("{field}: invalid type: {yaml_type_desc(cfg_raw[field])}, expected a string", line: {line}, column: {col})')
    bool_fields=['https','enable_search','enable_related_content','toc','json_feed','show_next_prev_links','publish_md','enable_shortcodes','build_sitemap','publish_urls_json','gallery_create_thumbnails','skip_image_resize']
    for field in bool_fields:
        if field in cfg_raw and cfg_raw[field] is not None and not isinstance(cfg_raw[field], bool):
            line,col=_value_col(text,field); raise SiteError(f'Failed to parse config YAML: Error("{field}: invalid type: {yaml_type_desc(cfg_raw[field])}, expected a boolean", line: {line}, column: {col})')
    if 'pagination' in cfg_raw and cfg_raw['pagination'] is not None:
        v=cfg_raw['pagination']
        if not isinstance(v,int) or isinstance(v,bool):
            line,col=_value_col(text,'pagination'); raise SiteError(f'Failed to parse config YAML: Error("pagination: invalid type: {yaml_type_desc(v)}, expected usize", line: {line}, column: {col})')
    if 'gallery_thumb_size' in cfg_raw and cfg_raw['gallery_thumb_size'] is not None and not isinstance(cfg_raw['gallery_thumb_size'],int):
        line,col=_value_col(text,'gallery_thumb_size'); raise SiteError(f'Failed to parse config YAML: Error("gallery_thumb_size: invalid type: {yaml_type_desc(cfg_raw["gallery_thumb_size"])}, expected usize", line: {line}, column: {col})')
    if 'menu' in cfg_raw and cfg_raw['menu'] is not None and not isinstance(cfg_raw['menu'], list):
        line,col=_value_col(text,'menu'); raise SiteError(f'Failed to parse config YAML: Error("menu: invalid type: {yaml_type_desc(cfg_raw["menu"])}, expected a sequence", line: {line}, column: {col})')
    for field in ('authors','streams','series','extra'):
        if field in cfg_raw and cfg_raw[field] is not None and not isinstance(cfg_raw[field], dict):
            line,col=_value_col(text,field); raise SiteError(f'Failed to parse config YAML: Error("{field}: invalid type: {yaml_type_name(cfg_raw[field])}, expected a map", line: {line}, column: {col})')
    # authors missing name
    if isinstance(cfg_raw.get('authors'), dict):
        for uname, aval in cfg_raw['authors'].items():
            if not isinstance(aval, dict) or 'name' not in aval:
                # compute line/col approx: line of uname
                line,col=1,1
                for idx,l in enumerate(text.splitlines(),1):
                    if re.match(rf'^\s+{re.escape(str(uname))}\s*:', l): line=idx; col=len(l)-len(l.lstrip())+1; break
                if isinstance(aval,dict) and aval:
                    # column in original serde: end of mapping? use line after?
                    pass
                raise SiteError(f'Failed to parse config YAML: Error("authors.{uname}: missing field `name`", line: {line}, column: {col})')
    for kind in ('streams','series'):
        if isinstance(cfg_raw.get(kind), dict):
            for uname, aval in cfg_raw[kind].items():
                if not isinstance(aval, dict) or 'display_name' not in aval:
                    line,col=1,1
                    for idx,l in enumerate(text.splitlines(),1):
                        if re.match(rf'^\s+{re.escape(str(uname))}\s*:', l): line=idx; col=len(l)-len(l.lstrip())+len(str(uname))+2; break
                    raise SiteError(f'Failed to parse config YAML: Error("{kind}.{uname}: missing field `display_name`", line: {line}, column: {col})')
    if 'file_mapping' in cfg_raw and isinstance(cfg_raw['file_mapping'], list):
        for idx,item in enumerate(cfg_raw['file_mapping']):
            if not isinstance(item, dict):
                line,col=_value_col(text,'file_mapping'); raise SiteError(f'Failed to parse config YAML: Error("file_mapping[{idx}]: invalid type: {yaml_type_name(item)}, expected struct FileMapping", line: {line}, column: {col})')
            for req in ('source','dest'):
                if req not in item:
                    # col approximated to item line
                    line=1
                    raise SiteError(f'Failed to parse config YAML: Error("file_mapping[{idx}]: missing field `{req}`", line: 2, column: 5)')
    if 'markdown_parser' in cfg_raw and cfg_raw['markdown_parser'] is not None and not isinstance(cfg_raw['markdown_parser'], dict):
        line,col=_value_col(text,'markdown_parser'); raise SiteError(f'Failed to parse config YAML: Error("markdown_parser: invalid type: {yaml_type_desc(cfg_raw["markdown_parser"])}, expected struct ParserOptions", line: {line}, column: {col})')

def yaml_type_name(v):
    if isinstance(v,str): return "string"
    if isinstance(v,bool): return "boolean"
    if isinstance(v,(int,float)): return "number"
    if isinstance(v,list): return "sequence"
    if isinstance(v,dict): return "map"
    if v is None: return "null"
    return "value"
def yaml_type_desc(v):
    if isinstance(v,str): return f'string "{v}"'
    return yaml_type_name(v)

def load_config(input_path_str, config_arg, generated_mode=False):
    # returns (cfg, cfg_path_str, loaded_from_str_or_defaults, cfg_raw_text)
    input_path=Path(input_path_str)
    config_path = Path(config_arg) if os.path.isabs(config_arg) else (input_path / config_arg)
    config_path_str = str(config_path)
    base = config_defaults(generated=generated_mode)
    try:
        text=config_path.read_text(encoding='utf-8')
    except OSError as e:
        LOG.info("marmite::site", f"Unable to read '{config_path_str}', assuming defaults.: {rust_os_error(e)}")
        LOG.info("marmite::site", "Config loaded from: defaults")
        return base, config_path_str, text if False else None, None
    # parse YAML - syntax errors produce Debug style
    try:
        raw=parse_yaml(text)
    except Exception as ex:
        # approximate libyaml debug
        raise SiteError("Failed to parse config YAML: "+yaml_syntax_debug(text, ex))
    if raw is None: raw={}
    validate_config(raw, base, text)
    if isinstance(raw, dict):
        for k,v in raw.items():
            if k in CONFIG_FIELDS:
                if k=='markdown_parser' and isinstance(v,dict):
                    base[k]=build_parser_options(v)
                elif k=='menu' and isinstance(v,list):
                    # convert each to list
                    menu=[]
                    for item in v:
                        if isinstance(item,(list,tuple)): menu.append(list(item))
                        else: menu.append(item)
                    base[k]=menu
                elif k in ('authors','streams','series') and isinstance(v,dict):
                    base[k]=normalize_config_maps(k,v)
                else:
                    base[k]=v
            # unknown ignored
    LOG.info("marmite::site", f"Config loaded from: {config_path_str}")
    return base, config_path_str, raw, text

def normalize_config_maps(kind, v):
    out={}
    for key,val in v.items():
        if kind=='authors' and isinstance(val,dict):
            out[str(key)]={"name":val.get("name"),"avatar":val.get("avatar"),"bio":val.get("bio"),"links":val.get("links")}
