def yaml_scalar(v):
    if v is None: return "null"
    if v is True: return "true"
    if v is False: return "false"
    if isinstance(v,(int,float)) and not isinstance(v,bool): return str(v)
    s=str(v)
    if s=="": return "''"
    # needs quoting if would parse as bool/null/number or contains special leading chars or ': ' ' #' etc
    needs=False
    if s.lower() in ("true","false","null","~","yes","no","on","off"): needs=True
    if re.fullmatch(r'[-+]?\d+(\.\d+)?', s): needs=True
    if s[0] in "!&*?|>%@`\"'#,[]{}:- " : 
        # '-' only if followed space, ':' handled below
        if not (s[0]=='-' and len(s)>1 and s[1]!=' '): needs=True
        if s[0] in "\"'": needs=True
    if ': ' in s or s.endswith(':'): needs=True
    if ' #' in s: needs=True
    if '\n' in s: needs=True
    if s.strip()!=s: needs=True
    if needs:
        return "'"+s.replace("'","''")+"'"
    return s

