def bin_name():
    return os.path.basename(sys.argv[0]) or "marmite"

def jaro(s1,s2):
    if s1==s2: return 1.0
    len1,len2=len(s1),len(s2)
    if len1==0 or len2==0: return 0.0
    match_distance=max(len1,len2)//2-1
    if match_distance<0: match_distance=0
    s1_matches=[False]*len1; s2_matches=[False]*len2; matches=0
    for i in range(len1):
        start=max(0,i-match_distance); end=min(i+match_distance+1,len2)
        for j in range(start,end):
            if s2_matches[j] or s1[i]!=s2[j]: continue
            s1_matches[i]=True; s2_matches[j]=True; matches+=1; break
    if matches==0: return 0.0
    k=0; transpositions=0
    for i in range(len1):
        if not s1_matches[i]: continue
        while not s2_matches[k]: k+=1
        if s1[i]!=s2[k]: transpositions+=1
        k+=1
    transpositions/=2
    return ((matches/len1)+(matches/len2)+((matches-transpositions)/matches))/3

def jaro_winkler(s1,s2):
    j=jaro(s1,s2); prefix=0
    for a,b in zip(s1,s2):
        if a==b and prefix<4: prefix+=1
        else: break
    return j + prefix*0.1*(1-j)

def suggest_long(name):
    best=None; bestscore=0
    for cand in LONG_OPTS.keys():
        sc=jaro_winkler(name,cand)
        # also boost prefix candidates a lot (clap suggests pag->pagination)
        if cand.startswith(name) and name: sc=max(sc,0.9)
        if sc>bestscore: bestscore=sc; best=cand
    if bestscore>=0.7: return best
    return None

class ClapExit(Exception):
    def __init__(self,code): self.code=code

def clap_error(msg, usage_options=None, default_usage=False, extra_tip=None):
    b=bin_name(); out=[]
    out.append(f"error: {msg}")
    out.append("")
    if extra_tip:
        out.append(f"  tip: {extra_tip}"); out.append("")
    if not default_usage and usage_options is None:
        # no usage (missing/invalid value errors)
        out.append("For more information, try '--help'.")
    else:
        if default_usage or not usage_options:
            out.append(f"Usage: {b} [OPTIONS] <INPUT_FOLDER> [OUTPUT_FOLDER]")
        else:
            parts=[OPT_DISPLAY[o] for o in OPT_ORDER if o in usage_options]
            out.append(f"Usage: {b} {' '.join(parts)} <INPUT_FOLDER> [OUTPUT_FOLDER]".replace("  "," "))
        out.append(""); out.append("For more information, try '--help'.")
    sys.stderr.write("\n".join(out)+"\n")
    raise ClapExit(2)

def print_help():
    sys.stdout.write(HELP_TEXT_TEMPLATE.format(bin=bin_name()))
    raise ClapExit(0)
def print_version():
    sys.stdout.write("marmite 0.2.7\n"); raise ClapExit(0)

def parse_cli(argv):
    args={
