        'generate_config':False,'init_site':False,'force':False,'shortcodes':False,'show_urls':False,'new':None,'edit':False,'page':False,'tags':None,
        'name':None,'tagline':None,'url':None,'https':None,'footer':None,'language':None,'pagination':None,'enable_search':None,'enable_related_content':None,
        'content_path':None,'templates_path':None,'static_path':None,'media_path':None,'default_date_format':None,'colorscheme':None,'toc':None,'json_feed':None,
        'show_next_prev_links':None,'publish_md':None,'source_repository':None,'image_provider':None,'theme':None,'build_sitemap':None,'publish_urls_json':None,
        'enable_shortcodes':None,'shortcode_pattern':None,'skip_image_resize':None,
        'input':None,'output':None
    }
    used=set(); positionals=[]; after_dd=False; i=0
    def usage_used(extra=None):
        s=set(used)
        if extra: s.add(extra)
        return s
    def set_value(field, typ, value, long_display):
        # validate
        if typ=='bool':
            if value not in ('true','false'):
                tip=None
                # similar value
                for cand in ('true','false'):
                    if jaro(value,cand)>=0.7: tip=f"a similar value exists: '{cand}'"
                msg=f"invalid value '{value}' for '{long_display}'\n  [possible values: true, false]"
                # clap formats tip after blank line before For more; our clap_error tip handling differs - assemble manually
                b=bin_name(); sys.stderr.write(f"error: {msg}\n")
                if tip: sys.stderr.write(f"\n  tip: {tip}\n")
                sys.stderr.write("\nFor more information, try '--help'.\n"); raise ClapExit(2)
            args[field]= (value=='true'); return
        if typ=='int':
            v=value
            err=None
            if v=='' : err="cannot parse integer from empty string"
            elif not re.fullmatch(r'\+?\d+', v):
                # negative or invalid
                if re.fullmatch(r'-\d+', v): err="invalid digit found in string"
                elif any(not c.isdigit() and c!='+' for c in v): err="invalid digit found in string"
                else: err="invalid digit found in string"
            else:
                num=int(v)
                if num>18446744073709551615: err="number too large to fit in target type"
                else: args[field]=num; return
            sys.stderr.write(f"error: invalid value '{value}' for '{long_display}': {err}\n\nFor more information, try '--help'.\n"); raise ClapExit(2)
        args[field]=value
    while i < len(argv):
        token=argv[i]
        if after_dd:
            positionals.append(token)
            if len(positionals)>2:
                clap_error(f"unexpected argument '{positionals[2]}' found", default_usage=True)
            i+=1; continue
        if token=='--':
            after_dd=True; i+=1; continue
        if token.startswith('--') and len(token)>2:
            body=token[2:]; value=None; has_eq=False
            if '=' in body:
                body, value = body.split('=',1); has_eq=True
            if body not in LONG_OPTS:
                sug=suggest_long(body)
                if body in ('help',): print_help()
                display_tok='--'+body
                if sug:
                    tip=f"a similar argument exists: '--{sug}'"
                    field_for_sug=LONG_OPTS[sug][0]
                    clap_error(f"unexpected argument '{display_tok}' found", usage_options=usage_used(field_for_sug), extra_tip=tip)
                else:
                    tip=f"to pass '{display_tok}' as a value, use '-- {display_tok}'"
                    # usage: if any used options, use them, else default
                    if used: clap_error(f"unexpected argument '{display_tok}' found", usage_options=usage_used(), extra_tip=tip)
                    else: clap_error(f"unexpected argument '{display_tok}' found", default_usage=True, extra_tip=tip)
            field, typ = LONG_OPTS[body]
            if field=='help':
                if has_eq: clap_error(f"unexpected value '{value}' for '--help' found; no more were expected", usage_options=usage_used('help'))
                print_help()
            if field=='version':
                if has_eq: clap_error(f"unexpected value '{value}' for '--version' found; no more were expected", usage_options=usage_used('version'))
                print_version()
            used.add(field)
            if typ=='flag':
                if field=='verbose':
                    if has_eq: clap_error(f"unexpected value '{value}' for '--verbose...' found; no more were expected", usage_options=usage_used())
                    args['verbose']+=1; i+=1; continue
                if has_eq:
                    clap_error(f"unexpected value '{value}' for '--{body}' found; no more were expected", usage_options=usage_used())
                args[field]=True; i+=1; continue
            # value option
            display=f"--{body} <{body.upper().replace('-','_')}>"
            # use canonical display from OPT_DISPLAY without leading --
            disp_full=OPT_DISPLAY[field]
            if has_eq:
                if value=='':
                    # error a value is required
                    extra=''
                    if typ=='bool': extra="\n  [possible values: true, false]"
                    sys.stderr.write(f"error: a value is required for '{disp_full}' but none was supplied{extra}\n\nFor more information, try '--help'.\n"); raise ClapExit(2)
                set_value(field,typ,value,disp_full); i+=1; continue
            # need next token not starting with - (except single -?)
            if i+1>=len(argv) or (argv[i+1].startswith('-') and argv[i+1]!='-'):
                # do not consume; if next is -1 etc, let main loop handle as unexpected; but if at end, missing value
                if i+1>=len(argv):
                    extra=''
                    if typ=='bool': extra="\n  [possible values: true, false]"
                    sys.stderr.write(f"error: a value is required for '{disp_full}' but none was supplied{extra}\n\nFor more information, try '--help'.\n"); raise ClapExit(2)
                # peek: if next is help/version, it will be handled next iteration, but clap would report missing value? We mimic --pagination -1 case: treat next as its own arg -> it will error unknown/help.
                # However append a pending missing check? For now continue without setting, marking field as used and let next token error/help.
                # To approximate missing case for e.g. --pagination --watch (valid flag), clap reports a value is required. Detect valid flag next:
                nxt=argv[i+1]
                if nxt.startswith('--') and nxt[2:].split('=')[0] in LONG_OPTS:
                    extra=''
                    if typ=='bool': extra="\n  [possible values: true, false]"
                    sys.stderr.write(f"error: a value is required for '{disp_full}' but none was supplied{extra}\n\nFor more information, try '--help'.\n"); raise ClapExit(2)
                i+=1; continue
            value=argv[i+1]; set_value(field,typ,value,disp_full); i+=2; continue
        if token.startswith('-') and token!='-' and len(token)>1:
            # short cluster
            cluster=token[1:]; j=0; consumed_next=False
            while j < len(cluster):
                ch=cluster[j]
                if ch not in SHORT_OPTS:
                    display_tok='-'+ch
                    tip=f"to pass '{display_tok}' as a value, use '-- {display_tok}'"
                    if used: clap_error(f"unexpected argument '{display_tok}' found", usage_options=usage_used(), extra_tip=tip)
                    else: clap_error(f"unexpected argument '{display_tok}' found", default_usage=True, extra_tip=tip)
                field,typ=SHORT_OPTS[ch]
                if field=='help': print_help()
                if field=='version': print_version()
                used.add(field)
                if typ=='flag':
                    if field=='verbose': args['verbose']+=1
                    else: args[field]=True
                    j+=1; continue
                # value short: rest of cluster is value, or =value, or next token
                rest=cluster[j+1:]
                disp_full=OPT_DISPLAY[field]
                if rest.startswith('='): rest=rest[1:]
                if rest!='':
                    set_value(field,typ,rest,disp_full); j=len(cluster); break
                if i+1>=len(argv) or (argv[i+1].startswith('-') and argv[i+1]!='-'):
                    if i+1>=len(argv):
                        sys.stderr.write(f"error: a value is required for '{disp_full}' but none was supplied\n\nFor more information, try '--help'.\n"); raise ClapExit(2)
                    i+=0; j=len(cluster); break
                set_value(field,typ,argv[i+1],disp_full); consumed_next=True; j=len(cluster); break
            i+= (2 if consumed_next else 1); continue
        # positional
        positionals.append(token)
        if len(positionals)>2:
            clap_error(f"unexpected argument '{token}' found", default_usage=True)
        i+=1
    # required checks
    missing=[]
    missing_opts=set()
    if args['bind_set'] or args['bind'] is not None:
        pass
    # bind tracking: bind_set set below in code? we set args['bind'] in set_value and used contains bind; detect used
    if 'bind' in used and not args['serve']:
        missing.append("--serve"); missing_opts.add('serve')
    if ('edit' in used or 'page' in used or 'tags' in used) and args['new'] is None:
        missing.append("--new <NEW>"); missing_opts.add('new')
    if len(positionals)<1:
        missing.append("<INPUT_FOLDER>")
    if missing:
        b=bin_name(); sys.stderr.write("error: the following required arguments were not provided:\n")
        for m in missing: sys.stderr.write(f"  {m}\n")
        sys.stderr.write("\n")
        opts=set(used)|missing_opts
        if opts:
            parts=[OPT_DISPLAY[o] for o in OPT_ORDER if o in opts]
            sys.stderr.write(f"Usage: {b} {' '.join(parts)} <INPUT_FOLDER> [OUTPUT_FOLDER]\n")
        else:
            sys.stderr.write(f"Usage: {b} <INPUT_FOLDER> [OUTPUT_FOLDER]\n")
        sys.stderr.write("\nFor more information, try '--help'.\n"); raise ClapExit(2)
    args['input']=positionals[0]; args['output']=positionals[1] if len(positionals)>1 else None
    args['_used']=used
