def bin_name():
    return os.path.basename(sys.argv[0]) or "marmite"

def jaro(s1,s2):
    if s1==s2: return 1.0
    len1,len2=len(s1),len(s2)
    if len1==0 or len2==0: return 0.0
    match_distance=max(len1,len2)//2-1
    if match_distance<0: match_distance=0
    s1_matches=[False]*len1; s2_matches=[False]*len2; matches=0
    for i in range(len1):
        start=max(0,i-match_distance); end=min(i+match_distance+1,len2)
        for j in range(start,end):
            if s2_matches[j] or s1[i]!=s2[j]: continue
            s1_matches[i]=True; s2_matches[j]=True; matches+=1; break
    if matches==0: return 0.0
    k=0; transpositions=0
    for i in range(len1):
        if not s1_matches[i]: continue
        while not s2_matches[k]: k+=1
        if s1[i]!=s2[k]: transpositions+=1
        k+=1
    transpositions/=2
    return ((matches/len1)+(matches/len2)+((matches-transpositions)/matches))/3

def jaro_winkler(s1,s2):
    j=jaro(s1,s2); prefix=0
    for a,b in zip(s1,s2):
        if a==b and prefix<4: prefix+=1
        else: break
    return j + prefix*0.1*(1-j)

def suggest_long(name):
    best=None; bestscore=0
    for cand in LONG_OPTS.keys():
        sc=jaro_winkler(name,cand)
        # also boost prefix candidates a lot (clap suggests pag->pagination)
        if cand.startswith(name) and name: sc=max(sc,0.9)
        if sc>bestscore: bestscore=sc; best=cand
    if bestscore>=0.7: return best
    return None

