# ---------- Date helpers ----------
def parse_date_value(s, path_str):
    s=str(s).strip()
    # formats with space datetime
    m=re.match(r'^(\d{4})-(\d{2})-(\d{2})[ ](\d{2}):(\d{2}):(\d{2})(?:\s*(?:[+-]\d{2}:?\d{2}|Z))?$', s)
    if m:
        try: return datetime.datetime(*(int(x) for x in m.groups()))
        except Exception: raise DateParseError(s,path_str,"trailing input")
    m=re.match(r'^(\d{4})-(\d{2})-(\d{2})[ ](\d{2}):(\d{2})$', s)
    if m:
        try: return datetime.datetime(*(int(x) for x in m.groups()))
        except Exception: raise DateParseError(s,path_str,"trailing input")
    m=re.match(r'^(\d{4})-(\d{2})-(\d{2})(?:$|T.*$| .*$)', s, re.S)
    if m:
        # if remainder starts with space but not a valid time, chrono would error trailing; but abc after T/date accepted
        rest=s[10:]
        if rest=='' or rest.startswith('T'):
            try: return datetime.datetime(int(m.group(1)),int(m.group(2)),int(m.group(3)))
            except Exception: raise DateParseError(s,path_str,"input is out of range")
        # space remainder not matching times above -> trailing input if time like numbers, else?
        if re.match(r'^ \d', rest):
            raise DateParseError(s,path_str,"trailing input")
        try: return datetime.datetime(int(m.group(1)),int(m.group(2)),int(m.group(3)))
        except Exception: raise DateParseError(s,path_str,"input is out of range")
    if re.fullmatch(r'\d{4}-\d{2}-\d{2}', s):
        raise DateParseError(s,path_str,"input is out of range")
    raise DateParseError(s,path_str,"premature end of input")

class DateParseError(Exception):
    def __init__(self,s,path,kind): super().__init__(s); self.date_str=s; self.path=path; self.kind=kind

def filename_date_and_slug(stem):
    # returns (date_or_None, slug_stem_after_prefix_or_original_stem)
    m=re.match(r'^(\d{4})-(\d{2})-(\d{2})(?:-(.*))?$', stem)
    if not m: return None, stem
    try: dt=datetime.datetime(int(m.group(1)),int(m.group(2)),int(m.group(3)))
    except: dt=None
    rest=m.group(4)
    if rest is None:
        return dt, stem
    # remove time segments: -HH-MM or -HH-MM-SS (each 2 digits) if present at start of rest
    tm=re.match(r'^(\d{2})-(\d{2})(?:-(\d{2}))?-(.+)$', rest)
    if tm:
        return dt, tm.group(4)
    return dt, rest

# ---------- Frontmatter ----------
def pod_repr(v):
    if isinstance(v,str): return json.dumps(v, ensure_ascii=False)
    if v is None: return "null"
    if isinstance(v,bool): return "true" if v else "false"
    if isinstance(v,(int,float)): return str(v)
    return json.dumps(v, ensure_ascii=False, separators=(',',':'))

def fm_extra_convert(v):
    if isinstance(v,dict): return {k:fm_extra_convert(val) for k,val in v.items()}
    if isinstance(v,list): return [fm_extra_convert(x) for x in v]
    if isinstance(v,int) and not isinstance(v,bool): return float(v)
    return v

def split_frontmatter(text, path_str):
    # returns (fm_dict_or_None, body, error_msg_or_None)
    if not text.startswith('---'):
        return None, text, None
    lines=text.split('\n')
    first=lines[0] if lines else ''
    if not first.startswith('---'):
        return None, text, None
    # find closing ---
    close_idx=None
    for i in range(1,len(lines)):
        if lines[i].strip()=='---':
            close_idx=i; break
    if close_idx is None:
        return None, text, "Invalid front matter format"
    fm_text='\n'.join(lines[1:close_idx])
    body='\n'.join(lines[close_idx+1:])
    if fm_text.strip()=='':
        return None, text, "Invalid front matter format"
    try:
        raw=parse_yaml(fm_text)
    except Exception as e:
        return None, text, fm_yaml_error(fm_text, e)
    if not isinstance(raw, dict):
        return None, text, "Invalid front matter format"
    # validate known field types
    valid=True
    if 'title' in raw and raw['title'] is not None and not isinstance(raw['title'],str): valid=False
    if 'slug' in raw and raw['slug'] is not None and not isinstance(raw['slug'],str): valid=False
    if 'tags' in raw and raw['tags'] is not None and not isinstance(raw['tags'],(str,list)): valid=False
    if 'authors' in raw and raw['authors'] is not None and not isinstance(raw['authors'],(str,list)): valid=False
    if 'author' in raw and raw['author'] is not None and not isinstance(raw['author'],(str,list)): valid=False
    if 'stream' in raw and raw['stream'] is not None and not isinstance(raw['stream'],str): valid=False
    if 'series' in raw and raw['series'] is not None and not isinstance(raw['series'],str): valid=False
    if 'pinned' in raw and raw['pinned'] is not None and not isinstance(raw['pinned'],bool): valid=False
    if 'banner_image' in raw and raw['banner_image'] is not None and not isinstance(raw['banner_image'],str): valid=False
    if 'extra' in raw and raw['extra'] is not None and not isinstance(raw['extra'],dict): valid=False
    if not valid:
        return None, text, "Invalid front matter format"
    return raw, body, None

def fm_yaml_error(fm_text, e):
    # try detect unbalanced [
    for idx,line in enumerate(fm_text.splitlines(),1):
        if '[' in line and ']' not in line:
            col=line.find('[')+1
            return f"Failed to parse YAML: did not find expected ',' or ']' at line {idx+1} column 1, while parsing a flow sequence at line {idx} column {col}"
        if ':' in line and line.strip().startswith(':'):
            return "Failed to parse YAML: did not find expected key, while parsing a block mapping"
    return f"Failed to parse YAML: {e}"

def parse_tags_value(v):
