def get_site_path_from_url(cfg):
    url=cfg.get("url") or ""
    try:
        parsed=urllib.parse.urlparse(url)
        if parsed.scheme in ('http','https') and parsed.netloc:
            p=parsed.path or ""
            if p=='/': return ""
            return p.rstrip('/')
    except Exception: pass
    return ""

