def build_toc(headings):
    if not headings: return ""
    out="<ul>\n"; current=1
    for level, text, slug in headings:
        while current < level: out+="<ul>\n"; current+=1
        while current > level: out+="</ul>\n"; current-=1
        out+=f'<li><a href="#{slug}">{htmlmod.escape(text)}</a></li>\n'
    while current>1: out+="</ul>\n"; current-=1
