# ---------- Site ----------
class Site:
    def __init__(self, input_str, output_str, cfg, cfg_path, args, content_root, start_time):
        self.input_str=input_str; self.output_str=output_str; self.cfg=cfg; self.cfg_path=cfg_path; self.args=args
        self.input_path=Path(input_str)
        self.output_base=Path(output_str) if output_str else (self.input_path/"site")
        site_path=cfg.get("site_path") or ""
        self.output_path=self.output_base / site_path if site_path else self.output_base
        self.content_root=content_root
        self.start_time=start_time
        self.fragments={}  # name -> rendered html
        self.fragments_raw={} # _name -> raw text
        self.contents=[]
        self.posts=[]; self.pages=[]
        self.groups={"tag":{},"archive":{},"author":{},"stream":{},"series":{}}
        self.galleries={}
        self.site_data={}
        self.generated_urls={"posts":[],"pages":[],"tags":[],"authors":[],"series":[],"streams":[],"archives":[],"feeds":[],"pagination":[],"file_mappings":[],"misc":[]}
        self.engine=None
        self.shortcode_templates={}  # name (without shortcodes/) -> template text
        self.shortcode_names=[]  # available names in collected order
        self.shortcode_collect_error=None
        self.global_context={}
        self.list_defs=[]

    # ----- path helpers -----
    def out_file(self, rel):
        return self.output_path / rel

    # ----- config/theme -----
    def theme_folder(self):
        theme=self.cfg.get("theme")
        if not theme: return None
        p=Path(theme)
        if p.is_absolute(): return p
        return self.input_path / p

    def build(self):
        cfg=self.cfg
        # pagination zero panic before output creation (observed site.rs:206)
        if cfg.get("pagination")==0:
            rust_panic("src/site.rs:206:49", "attempt to divide by zero")
        # galleries (collect data)
        self.collect_galleries()
        # contents and fragments
        self.collect_contents()
        # site data / groups / next-prev / backlinks
        self.build_site_data()
        # If show_urls, caller handles after build_site_data without rendering/output
        return True

    def collect_galleries(self):
        cfg=self.cfg
        gallery_root=self.content_root / (cfg.get("media_path") or "media") / (cfg.get("gallery_path") or "gallery")
        LOG.info("marmite::gallery", f"Processing galleries from: {gallery_root}")
        if not gallery_root.is_dir():
            LOG.info("marmite::gallery", f"Gallery directory does not exist: {gallery_root}")
            return
        galleries={}
        try: entries=list(os.scandir(gallery_root))
        except Exception: entries=[]
        for entry in entries:
            if not entry.is_dir(): continue
            album=entry.name; files=[]
            album_path=Path(entry.path)
            try: file_entries=list(os.scandir(album_path))
            except: file_entries=[]
            for fe in file_entries:
                if fe.is_dir(): continue
                ext=Path(fe.name).suffix.lower()
                if ext in ('.jpg','.jpeg','.png','.gif','.webp','.svg','.bmp','.avif'):
                    files.append({"thumb":f"thumbnails/{fe.name}","image":fe.name,"description":None})
            if files:
                galleries[album]={"name":album,"files":files,"cover":files[0]["image"],"ord":"asc"}
                LOG.info("marmite::gallery", f"Found gallery: {album} with {len(files)} files")
        self.galleries=galleries
        if galleries: LOG.info("marmite::gallery", f"Total galleries found: {len(galleries)}")

    def collect_contents(self):
        cfg=self.cfg
        # walk content root recursively preserving scandir order depth-first
        files=[]
        def walk(dirpath):
            try: entries=list(os.scandir(dirpath))
            except Exception: return
            for e in entries:
                p=Path(e.path)
                if e.is_dir():
                    walk(p)
                elif e.is_file() and p.name.endswith('.md'):
                    files.append(p)
        walk(self.content_root)
        # fragments: only content_root top-level _*.md ?
        # First pass: collect raw fragments for markdown header/footer/references and all _ files at root
        for p in files:
            if p.parent==self.content_root and p.name.startswith('_'):
                raw=p.read_text(encoding='utf-8', errors='strict') if True else ""
                stem=p.stem  # _hero
                self.fragments_raw[stem]=raw
        # render fragments using markdown (no fm)
        renderer=MdRenderer(cfg.get("markdown_parser"))
        for stem, raw in self.fragments_raw.items():
            name=stem[1:] if stem.startswith('_') else stem
            if stem in ('_markdown_header','_markdown_footer','_references','_404'): continue
            # fragment markdown rendering: no title extraction
            self.fragments[name]=renderer.render(raw)
        collector=ContentCollector(self)
        contents=[]
        for p in files:
            if p.name.startswith('_'): continue
            try:
                c=collector.parse_file(p)
            except DateParseError as e:
                LOG.error("marmite::content", f"ERROR: Invalid date format {e.date_str} when parsing {e.path}, {e.kind}")
                raise SystemExit(1)
            if c is not None: contents.append(c)
        self.contents=contents

    def build_site_data(self):
        # posts/pages
        posts=[c for c in self.contents if c.get("date")]
        pages=[c for c in self.contents if not c.get("date")]
        # site_data.posts sorted date desc stable
        posts_sorted=sorted(posts, key=lambda c: c.get("date") or "", reverse=True)
        # pages sorted title desc stable
        pages_sorted=sorted(pages, key=lambda c: c.get("title") or "", reverse=True)
        self.posts=posts_sorted; self.pages=pages_sorted
        # groups from posts_sorted
        groups={"tag":{},"archive":{},"author":{},"stream":{},"series":{}}
        for c in posts_sorted:
            for t in c.get("tags") or []: groups["tag"].setdefault(t,[]).append(c)
            if c.get("date"):
                year=c["date"][:4]; groups["archive"].setdefault(year,[]).append(c)
            for a in c.get("authors") or []: groups["author"].setdefault(a,[]).append(c)
            if c.get("stream"): groups["stream"].setdefault(c["stream"],[]).append(c)
            if c.get("series"): groups["series"].setdefault(c["series"],[]).append(c)
        self.groups=groups
        # next/prev among posts ascending date (stable original order? ascending sort by date)
        asc=sorted(posts, key=lambda c: c.get("date") or "")
        # snapshots
        def snapshot(c):
            if c is None: return None
            s=dict(c); s["links_to"]=None; s["back_links"]=[]; s["next"]=None; s["previous"]=None; s.pop('_headings',None); return s
        for idx,c in enumerate(asc):
            # find corresponding object in self.contents (same dict)
            prev_c=asc[idx-1] if idx>0 else None
            next_c=asc[idx+1] if idx < len(asc)-1 else None
            c["previous"]=snapshot(prev_c); c["next"]=snapshot(next_c)
        # backlinks: for each content, others whose links_to contains slug
        for c in self.contents:
            backs=[]
            for other in self.contents:
                if other is c: continue
                lt=other.get("links_to")
                if lt and c.get("slug") in lt:
                    backs.append(snapshot(other))
            c["back_links"]=backs
        # site_data dict (contents references cleaned for tera: remove _headings from serialization? Keep dict but json_encode would include _headings -> need remove before building context)
        for c in self.contents: c.pop('_headings',None)
        # But we need headings for toc shortcode per current content: toc already generated. card etc no.
        self.site_data={
            "site": self.cfg_for_templates(),
            "posts": posts_sorted, "pages": pages_sorted,
            "tag":{"kind":"Tag","map":groups["tag"]},
            "archive":{"kind":"Archive","map":groups["archive"]},
            "author":{"kind":"Author","map":groups["author"]},
            "stream":{"kind":"Stream","map":groups["stream"]},
            "series":{"kind":"Series","map":groups["series"]},
            "latest_timestamp": None, "config_path": self.cfg_path, "force_render": bool(self.args.get('force')),
            "generated_urls": self.generated_urls, "galleries": self.galleries
        }

    def cfg_for_templates(self):
        # config dict as context (same as marmite cfg but authors values etc already normalized)
        return self.cfg

    # ----- templates & shortcodes loading -----
    def load_templates(self):
        templates={}
        assets=get_assets()
        # embedded default templates
        for rel in assets.list_prefix("default_templates/"):
            name=rel[len("default_templates/"):]
            templates[name]=assets.get(rel).decode('utf-8')
        # shortcode embedded later added
        # theme
        theme_folder=self.theme_folder()
        if theme_folder is not None:
            if not theme_folder.is_dir():
                LOG.error("marmite::config", f"Theme folder '{theme_folder}' does not exist"); raise SystemExit(1)
            tpl_dir=theme_folder/"templates"
            if tpl_dir.is_dir():
                for p in sorted(tpl_dir.rglob("*")):
                    if p.is_file():
                        templates[p.name]=p.read_text(encoding='utf-8')
        else:
            # user templates
            tpl_root=self.input_path / (self.cfg.get("templates_path") or "templates")
            if tpl_root.is_dir():
                for p in tpl_root.rglob("*"):
                    if p.is_file():
                        # template name is filename only? Tera loads by relative? init templates are flat. Recursive subfolders: name relative posix
                        rel=p.relative_to(tpl_root).as_posix()
                        templates[rel]=p.read_text(encoding='utf-8')
                        # also flat name for compatibility? Original Tera add_template_files with path as name probably filename only for top-level. Keep rel.
            # if theme exists but also user templates should be ignored (observed)
        # shortcodes collection
        sc_templates, sc_names, sc_error = self.collect_shortcodes()
        self.shortcode_templates=sc_templates; self.shortcode_names=sc_names; self.shortcode_collect_error=sc_error
        if sc_error:
            LOG.error("marmite::site", f"Failed to collect shortcodes: {sc_error}")
        templates.update(sc_templates)
        # functions
        cfg=self.cfg
        def group_fn(ctx=None, *pos, **kwargs):
            kind=kwargs.get('kind', pos[0] if pos else '')
            mapping=self.groups.get(kind, {})
            return mapping
        def stream_display(ctx=None, *pos, **kwargs):
            stream=kwargs.get('stream', pos[0] if pos else '')
            info=(cfg.get("streams") or {}).get(stream)
            if isinstance(info,dict) and info.get("display_name"): return info["display_name"]
            return stream
        def series_display(ctx=None, *pos, **kwargs):
            series=kwargs.get('series', pos[0] if pos else '')
            info=(cfg.get("series") or {}).get(series)
            if isinstance(info,dict) and info.get("display_name"): return info["display_name"]
            return series
        def source_link_fn(ctx=None, *pos, **kwargs):
            content=kwargs.get('content', pos[0] if pos else None)
            if not isinstance(content,dict): return ""
            sp=content.get("source_path")
            if not sp: return ""
            filename=Path(str(sp)).name
            repo=cfg.get("source_repository")
            if repo: return f"{repo}/{filename}"
            if cfg.get("publish_md"): return filename
            return ""
        functions={"url_for": make_url_for(cfg), "group": group_fn, "stream_display_name": stream_display, "series_display_name": series_display, "source_link": source_link_fn}
        try:
            self.engine=Engine(templates, functions=functions, default_date_format=cfg.get("default_date_format") or "%b %e, %Y")
        except Exception as e:
            LOG.error("marmite::site", f"Failed to load templates: {e}"); raise SystemExit(1)
        # global context
        gc={}
        gc["site"]=self.cfg_for_templates(); gc["site_data"]=self.site_data; gc["menu"]=cfg.get("menu"); gc["language"]=cfg.get("language")
        # fragments override? fragments are keys
        for k,v in self.fragments.items(): gc[k]=v
        self.global_context=gc

    def collect_shortcodes(self):
        # returns (templates_dict name->text, names list, error_or_None)
        templates={}
        names=[]
        embedded=embedded_shortcode_templates()
        for full, text in embedded.items():
            templates[full]=text; names.append(full.split('/',1)[1])
        # user shortcodes
        sc_dir=self.input_path/"shortcodes"
        error=None
        if sc_dir.is_dir():
            for p in sorted(sc_dir.iterdir()):
                if p.is_file() and p.suffix=='.html':
                    text=p.read_text(encoding='utf-8')
                    macros=re.findall(r'\{%-?\s*macro\s+(\w+)\s*\(', text)
                    if not macros:
                        error=f"HTML shortcode file {p} must contain at least one macro"
                        continue
                    stem=p.stem
                    templates[f"shortcodes/{stem}"]=text
                    if stem not in names: names.append(stem)
                    LOG.debug("marmite::shortcodes", f"Loaded shortcode: {stem}")
        else:
            LOG.debug("marmite::shortcodes", f"No shortcodes directory found at {sc_dir}")
        for n in ['authors','card','gallery','pages','posts','series','socials','spotify','streams','tags','toc','youtube']:
            LOG.debug("marmite::shortcodes", f"Loaded embedded shortcode: {n}")
        # Names order for --shortcodes: alphabetical by engine later
        return templates, names, error

