                    shutil.copyfile(p,dest)
        # galleries thumbnails
        if cfg.get("gallery_create_thumbnails"):
            for album, gal in self.galleries.items():
                for f in gal.get("files",[]):
                    src=media_src/(cfg.get("gallery_path") or "gallery")/album/f["image"]
                    dest=self.output_path/media_rel/(cfg.get("gallery_path") or "gallery")/album/f["thumb"]
                    dest.parent.mkdir(parents=True, exist_ok=True)
                    if src.is_file(): make_thumbnail(src,dest, int(cfg.get("gallery_thumb_size") or 50))
        # file_mappings
        for fm in cfg.get("file_mapping") or []:
            if isinstance(fm,dict) and fm.get("source") and fm.get("dest"):
                src=self.input_path/fm["source"]; dest=self.output_path/fm["dest"]
                if src.is_file(): dest.parent.mkdir(parents=True, exist_ok=True); shutil.copyfile(src,dest)
        # publish_md copies later in render? source files copied to output root
