    def _write_embedded_static(self, static_out_rel):
        assets=get_assets()
        # order as observed log: files sorted by asset order: Atkinson, avatar, colorschemes..., custom.css etc.
        # Our list_prefix sorted gives alphabetical: Atkinson, avatar, colorschemes/*, custom.css, custom.js, favicon, logo, marmite...
        for rel in assets.list_prefix("default_static/"):
            name=rel[len("default_static/"):]
            dest=self.output_path/static_out_rel/name; dest.parent.mkdir(parents=True, exist_ok=True); dest.write_bytes(assets.get(rel))
            LOG.info("marmite::embedded", f"Generated {dest}")

    def _copy_root_custom(self, static_out_rel):
        # custom.css/js/favicon from root/input, else from output static fallback (self copy logging)
        for fname in ("custom.css","custom.js","favicon.ico"):
            dest=self.output_path/static_out_rel/fname
            candidates=[self.input_path/fname, self.input_path/(self.cfg.get("static_path") or "static")/fname, dest]
            src=None
            for cand in candidates:
                if cand.is_file(): src=cand; break
            if src is not None:
                dest.parent.mkdir(parents=True, exist_ok=True)
                if src.resolve()!=dest.resolve() if dest.exists() else True:
                    shutil.copyfile(src,dest)
                LOG.info("marmite::site", f"Copied {src} to {dest}")
            # if root custom in content folder? ignore
        # robots
        dest=self.output_path/"robots.txt"
        candidates=[self.input_path/"robots.txt", self.input_path/(self.cfg.get("static_path") or "static")/"robots.txt", self.output_path/static_out_rel/"robots.txt"]
        src=None
        for cand in candidates:
            if cand.is_file(): src=cand; break
        if src is not None:
            if not (dest.exists() and src.resolve()==dest.resolve()): shutil.copyfile(src,dest)
            LOG.info("marmite::site", f"Copied {src} to {dest}")

    def generate_search_index(self, static_out_rel):
        items=[]
        for c in self.posts:
            if c.get("stream")=="draft": continue
            items.append({"title":c.get("title"),"description":c.get("description"),"tags":c.get("tags"),"slug":c.get("slug"),"html":striptags(c.get("html") or "").strip()})
        for c in self.pages:
            items.append({"title":c.get("title"),"description":c.get("description"),"tags":c.get("tags"),"slug":c.get("slug"),"html":striptags(c.get("html") or "").strip()})
        dest=self.output_path/static_out_rel/"search_index.json"; dest.parent.mkdir(parents=True, exist_ok=True)
        dest.write_text(json.dumps(items, ensure_ascii=False, separators=(',',':')), encoding='utf-8')

    # ----- lists -----
    def sorted_list_contents(self, contents):
        # pinned first, then date desc, stable
        return sorted(contents, key=lambda c: (1 if c.get("pinned") else 0, c.get("date") or ""), reverse=True)

    def prepare_lists_and_urls(self):
        cfg=self.cfg
        # We'll compute list definitions; each def: base filename without .html (e.g. index, tag-x), title_base, items (full), feed_name or None, kind
        defs=[]
        # index
        index_items=[c for c in self.posts if c.get("stream")=="index"]
        index_items=self.sorted_list_contents(index_items)
        defs.append({"base":"index","title":None,"items":index_items,"feed":"index","is_index":True})
        # group individual lists - iterate groups; order deterministic insertion
        for tag, items in self.groups["tag"].items():
            slug=slugify(tag); defs.append({"base":f"tag-{slug}","title":(cfg.get("tags_content_title") or "").replace("$tag",tag),"items":self.sorted_list_contents(items),"feed":f"tag-{slug}"})
        for author, items in self.groups["author"].items():
            slug=slugify(author); title=author
            ainfo=(cfg.get("authors") or {}).get(author)
            if isinstance(ainfo,dict) and ainfo.get("name"): title=ainfo["name"]
            author_obj=self._author_obj(author)
            defs.append({"base":f"author-{slug}","title":title,"items":self.sorted_list_contents(items),"feed":f"author-{slug}","author":author_obj})
        for series, items in self.groups["series"].items():
            slug=slugify(series); defs.append({"base":f"series-{slug}","title":(cfg.get("series_content_title") or "").replace("$series",series),"items":self.sorted_list_contents(items),"feed":f"series-{slug}"})
        for stream, items in self.groups["stream"].items():
            if stream=="index": continue
            slug=slugify(stream); base=slug  # stream file is slug.html (not stream-)
            defs.append({"base":base,"title":(cfg.get("streams_content_title") or "").replace("$stream",stream),"items":self.sorted_list_contents(items),"feed":base})
        for year, items in self.groups["archive"].items():
            defs.append({"base":f"archive-{year}","title":(cfg.get("archives_content_title") or "").replace("$year",year),"items":self.sorted_list_contents(items),"feed":f"archive-{year}"})
        # pages list
        defs.append({"base":"pages","title":cfg.get("pages_title"),"items":list(self.pages),"feed":None,"is_pages":True})
        self.list_defs=defs
        # generated urls
        gu=self.generated_urls
        gu["posts"]=[format_public_url(cfg, f"{c['slug']}.html") for c in self.posts]
        gu["pages"]=[format_public_url(cfg, f"{c['slug']}.html") for c in self.pages]
        if self.pages: gu["pages"].append(format_public_url(cfg,"pages.html"))
        gu["tags"]=[format_public_url(cfg, f"tag-{slugify(t)}.html") for t in self.groups["tag"].keys()]
        if self.groups["tag"]: gu["tags"].append(format_public_url(cfg,"tags.html"))
        gu["authors"]=[format_public_url(cfg, f"author-{slugify(a)}.html") for a in self.groups["author"].keys()]
        if self.groups["author"]: gu["authors"].append(format_public_url(cfg,"authors.html"))
        gu["series"]=[format_public_url(cfg, f"series-{slugify(s)}.html") for s in self.groups["series"].keys()]
        if self.groups["series"]: gu["series"].append(format_public_url(cfg,"series.html"))
        gu["streams"]=[format_public_url(cfg, f"{slugify(s)}.html") for s in self.groups["stream"].keys() if s!="index"]
        if self.groups["stream"]: gu["streams"].append(format_public_url(cfg,"streams.html"))
        gu["archives"]=[format_public_url(cfg, f"archive-{y}.html") for y in self.groups["archive"].keys()]
        if self.groups["archive"]: gu["archives"].append(format_public_url(cfg,"archive.html"))
        # feeds/pagination computed from defs
        feeds=[]; pagination=[]
        for d in defs:
            items=d["items"]; per=int(cfg.get("pagination") or 10)
            total_pages=(len(items)+per-1)//per if items else 0
            if d.get("feed") and items:
                feeds.append(format_public_url(cfg, f"{d['feed']}.rss"))
                if cfg.get("json_feed"): feeds.append(format_public_url(cfg, f"{d['feed']}.json"))
            if items:
                for i in range(1,total_pages+1): pagination.append(format_public_url(cfg, f"{d['base']}-{i}.html"))
        gu["feeds"]=feeds; gu["pagination"]=pagination
        gu["file_mappings"]=[format_public_url(cfg, fm.get("dest")) for fm in (cfg.get("file_mapping") or []) if isinstance(fm,dict) and fm.get("dest")]
        gu["misc"]=[format_public_url(cfg,"index.html")]
        self.site_data["generated_urls"]=gu

    def _author_obj(self, username):
        ainfo=(self.cfg.get("authors") or {}).get(username)
        if isinstance(ainfo,dict):
            return {"name":ainfo.get("name"),"avatar":ainfo.get("avatar"),"bio":ainfo.get("bio"),"links":ainfo.get("links")}
        return {"name":username,"avatar":"static/avatar-placeholder.png","bio":"","links":None}

    def render_all(self):
        cfg=self.cfg
        # group pages first
        group_pages=[("tags","tag",cfg.get("tags_title")),("authors","author",cfg.get("authors_title")),("archive","archive",cfg.get("archives_title")),("streams","stream",cfg.get("streams_title")),("series","series",cfg.get("series_title"))]
        for filename, kind, title in group_pages:
            context={"title":title,"kind":kind,"current_page":f"{filename}.html"}
            rendered=self.render_template_to_file("group.html", context, f"{filename}.html")
            self.write_output(f"{filename}.html", rendered); LOG.info("marmite::site", f"Generated {self.output_path/(filename+'.html')}")
        # lists
        for d in self.list_defs:
            self.render_list_def(d)
        # 404
        self.render_404()
        # contents
        for c in self.contents:
            self.render_content(c)
        # publish_md
        if cfg.get("publish_md"):
            for c in self.contents:
                sp=c.get("source_path")
                if sp and Path(sp).is_file():
                    dest=self.output_path/Path(sp).name; shutil.copyfile(sp,dest)

    def render_list_def(self, d):
        cfg=self.cfg; per=int(cfg.get("pagination") or 10); items=d["items"]; base=d["base"]
        total_pages=(len(items)+per-1)//per if items else 0
        total_for_context=max(1,total_pages)
        # helper to render one page
        def do_render(filename, title, page_num, slice_items):
            context={"title":title,"content_list":slice_items,"current_page":filename,"current_page_number":page_num,"total_pages":total_for_context}
            if page_num>1: context["previous_page"]=f"{base}-{page_num-1}.html" if not (base=="index" and page_num==2 and False) else f"{base}-{page_num-1}.html"
            # previous for page 2 should be base-1.html (not base.html) observed index-2 prev index-1
            if total_for_context>page_num: context["next_page"]=f"{base}-{page_num+1}.html"
            if "author" in d: context["author"]=d["author"]
            template="list.html"
            if d.get("is_index") and self.engine.has_template("custom_index.html"): template="custom_index.html"
            rendered=self.render_template_to_file(template, context, filename)
            self.write_output(filename, rendered); LOG.info("marmite::site", f"Generated {self.output_path/filename}")
        if not items:
            # only base
            title=d["title"]
            if d.get("is_index"): title="Welcome to Marmite"
            do_render(f"{base}.html", title if title is not None else "", 1, [])
            return
        # base file
        for i in range(1,total_pages+1):
            slice_items=items[(i-1)*per:i*per]
            # paginated title
            if d.get("is_index"):
                pag_title=f"Page - {i}"
            else:
                pag_title=f"{d['title']} - {i}"
            do_render(f"{base}-{i}.html", pag_title, i, slice_items)
        # base duplicate
        base_title=d["title"]
        if d.get("is_index"): base_title=""
        do_render(f"{base}.html", base_title, 1, items[0:per])
        # feeds
        if d.get("feed"):
            self.generate_feeds(d)

    def render_404(self):
        cfg=self.cfg
        # construct content
        raw=self.fragments_raw.get('_404')
        if raw is not None:
            # parse as content like: title from first heading line, html rendered full (no title removal)
            # Use markdown render full
            renderer=MdRenderer(cfg.get("markdown_parser"))
            html=renderer.render(raw)
            # title: first heading text or first line?
            title="Page not found"
            # extract from html h1/h2... or raw lines
            m=re.search(r'<h[1-6]><a[^>]*></a>(.*?)</h[1-6]>', html, re.S)
            if m: title=striptags(m.group(1)).strip()
            else:
                for line in raw.split('\n'):
                    if line.strip(): title=line.strip().lstrip('#').strip(); break
            content={"title":title,"description":None,"slug":"404","html":html,"tags":[],"date":None,"extra":None,"links_to":None,"back_links":[],"card_image":None,"banner_image":None,"authors":[],"stream":None,"series":None,"pinned":False,"toc":None,"modified_time":None,"comments":None,"next":None,"previous":None,"source_path":None}
        else:
            content={"title":"Page not found","description":None,"slug":"404","html":"Page not found :/","tags":[],"date":None,"extra":None,"links_to":None,"back_links":[],"card_image":None,"banner_image":None,"authors":[],"stream":None,"series":None,"pinned":False,"toc":None,"modified_time":None,"comments":None,"next":None,"previous":None,"source_path":None}
        context={"content":content,"title":content["title"],"current_page":"404.html"}
        rendered=self.render_template_to_file("content.html", context, "404.html")
        # no shortcode processing for 404
        self.write_output("404.html", rendered); LOG.info("marmite::site", f"Generated {self.output_path/'404.html'}")

    def render_content(self, c):
        filename=f"{c['slug']}.html"
        context={"content":c,"title":c.get("title"),"current_page":filename}
        rendered=self.render_template_to_file("content.html", context, filename)
        # shortcodes
        if self.cfg.get("enable_shortcodes"):
            rendered=self.process_shortcodes(rendered, c)
        # wikilinks postprocessing is no-op (handled in markdown)
        self.write_output(filename, rendered); LOG.info("marmite::site", f"Generated {self.output_path/filename}")

    def process_shortcodes(self, html_text, current_content):
        if self.shortcode_collect_error:
            # processor still available? Original when collect error due bad file, shortcodes render as not found for that file but embedded still? It logged error and each shortcode gave not found for custom names. Embedded still work? We'll proceed with available templates.
            pass
        pattern_str=self.cfg.get("shortcode_pattern") or r'<!-- \.(\w+)(?:\s+([^-][\s\S]*?))?\s*-->'
        try:
            pattern=re.compile(pattern_str)
        except Exception:
            return html_text
        def replace(m):
            name=m.group(1)
            params=''
            try: params=m.group(2) or ''
            except Exception: params=''
            params=params.strip()
            LOG.info("marmite::shortcodes", f"Processing shortcode: name='{name}', params='{params}', full_match='{m.group(0)}'")
            return self.render_shortcode(name, params, current_content)
        return pattern.sub(replace, html_text)

    def render_shortcode(self, name, params, current_content):
        # build macro args string
        args=[]
        if params:
            # tokenize key=value pairs (values may be quoted or bare with spaces in quotes)
            for key, val in parse_shortcode_params(params):
                # all values become strings in original conversion
                args.append(f'{key}="{val}"')
        macro_args=', '.join(args)
        template_text=f'{{% import "shortcodes/{name}" as sc -%}}\n    {{{{ sc::{name}({macro_args}) }}}}'
        # check existence
        if f"shortcodes/{name}" not in self.engine.templates:
            err_msg=f"Shortcode '{name}' not found"
            LOG.warn("marmite::shortcodes", f"Shortcode '{name}' failed to render: {err_msg}")
            return shortcode_error_html(err_msg)
        # context: global + content (for toc/card)
        ctx=dict(self.global_context); ctx["content"]=current_content
        try:
            result=self.engine.render_string(template_text, ctx)
            return result
        except MacroError as e:
            err_msg=f"Failed to render shortcode '{name}': Failed to render '__tera_one_off': error while rendering macro `sc::{name}`"
            LOG.warn("marmite::shortcodes", f"Shortcode '{name}' failed to render: {err_msg}")
            return shortcode_error_html(err_msg)
        except Exception as e:
            # generic tera render failure in macro args / missing required
            err_msg=f"Failed to render shortcode '{name}': Failed to render '__tera_one_off'"
            LOG.warn("marmite::shortcodes", f"Shortcode '{name}' failed to render: {err_msg}")
            return shortcode_error_html(err_msg)

    # ----- feeds, sitemap, urls, marmite.json -----
