def config_for_json(cfg):
    # cfg already in canonical order; ensure parser options ordering: when markdown_parser present, output sections render, parse, extension in that order (our build already)
    return cfg

def shortcode_error_html(msg):
    escaped=msg.replace('&','&amp;').replace('<','&lt;').replace('>','&gt;').replace('"','&quot;').replace("'","&#39;")
    return f'<div class="shortcode-error" style="border: 2px solid red; padding: 10px; margin: 10px 0; background-color: #ffeeee; color: #cc0000;">\n                        <strong>Shortcode Error:</strong> {escaped}</div>'

def parse_shortcode_params(params):
    out=[]; i=0; n=len(params)
    while i<n:
        while i<n and params[i].isspace(): i+=1
        if i>=n: break
        m=re.match(r'(\w+)=', params[i:])
        if not m:
            # bare token ignored? skip to next space
            while i<n and not params[i].isspace(): i+=1
            continue
        key=m.group(1); i+=len(m.group(0))
        if i<n and params[i] in ('"',"'"):
            q=params[i]; end=params.find(q,i+1); 
            if end==-1: val=params[i+1:]; i=n
            else: val=params[i+1:end]; i=end+1
        else:
            start=i
            while i<n and not params[i].isspace(): i+=1
            val=params[start:i]
        out.append((key,val))
    return out

def generate_rss(cfg, feed_name, items):
    base=get_base_url(cfg)
    def xml_escape(s): return htmlmod.escape(str(s), quote=True)
    latest=None
    for c in items:
        if c.get("date"): latest=c.get("date"); break
    pub_date=rss_date(latest) if latest else rss_date_now()
    last_build=rss_date_now()
    parts=[f'<?xml version="1.0" encoding="utf-8"?><rss version="2.0" xmlns:content="http://purl.org/rss/1.0/modules/content/"><channel><title>{xml_escape(cfg.get("name") or "")}</title><link>{base}</link><description>{xml_escape(cfg.get("tagline") or "")}</description><pubDate>{pub_date}</pubDate><lastBuildDate>{last_build}</lastBuildDate><generator>marmite</generator>']
    for c in items:
        link=f"{base}/{c.get('slug')}.html"
        parts.append('<item>')
        parts.append(f"<title>{xml_escape(c.get('title') or '')}</title>")
        parts.append(f"<link>{link}</link>")
        if c.get("description") is not None: parts.append(f"<description><![CDATA[{c.get('description')}]]></description>")
        if c.get("authors"): parts.append(f"<author>{xml_escape(c['authors'][0])}</author>")
        for t in c.get("tags") or []: parts.append(f"<category>{xml_escape(t)}</category>")
        parts.append(f"<guid>{link}</guid>")
        if c.get("date"): parts.append(f"<pubDate>{rss_date(c.get('date'))}</pubDate>")
        parts.append(f'<source url="{base}">{feed_name}</source>')
        parts.append(f"<content:encoded><![CDATA[{c.get('html') or ''}]]></content:encoded>")
        parts.append('</item>')
    parts.append('</channel></rss>')
    return ''.join(parts)

def rss_date(date_str):
    # input ISO naive
    try: dt=datetime.datetime.strptime(date_str, "%Y-%m-%dT%H:%M:%S")
    except: 
        try: dt=datetime.datetime.fromisoformat(date_str)
        except: dt=datetime.datetime.utcnow()
    return dt.strftime("%a, %d %b %Y %H:%M:%S GMT")
def rss_date_now():
    return datetime.datetime.utcnow().strftime("%a, %d %b %Y %H:%M:%S GMT")

def generate_json_feed(cfg, feed_name, items):
    data={"version":"https://jsonfeed.org/version/1","title":cfg.get("name"),"home_page_url":cfg.get("url") or "","feed_url":format_public_url(cfg, f"{feed_name}.json"),"description":cfg.get("tagline") or "","items":[]}
    for c in items:
        url=format_public_url(cfg, f"{c.get('slug')}.html")
        authors=[]
        for a in c.get("authors") or []: authors.append({"name":a,"url":"","avatar":""})
        item={"id":url,"url":url,"title":c.get("title"),"content_html":c.get("html"),"summary":c.get("description") or "","date_published": (f"{c.get('date')}-00:00" if c.get("date") else None),"image":c.get("card_image") or "","authors":authors,"tags":c.get("tags") or [],"language":cfg.get("language")}
        # if date is None, original may omit? Keep as None? Posts always have date in feeds.
        if item["date_published"] is None: item.pop("date_published")
        data["items"].append(item)
    return json.dumps(data, indent=2, ensure_ascii=False)

def format_tera_error(e, template_name, dest, engine):
    # Construct Rust Debug-like error string
    inner=str(e)
    # determine kind
    kind=getattr(e,'kind',None); func=getattr(e,'func',None)
    if kind=="CallFunction" and func:
        inner_msg=getattr(e,'inner',inner)
        return ("Error {\n"
                "        kind: Msg(\n"
                f"            \"Failed to render '{template_name}'\",\n"
                "        ),\n"
                "        source: Some(\n"
                "            Error {\n"
                "                kind: CallFunction(\n"
                f"                    \"{func}\",\n"
                "                ),\n"
                "                source: Some(\n"
                "                    Error {\n"
                "                        kind: Msg(\n"
                f"                            \"{inner_msg}\",\n"
                "                        ),\n"
                "                        source: None,\n"
                "                    },\n"
                "                ),\n"
                "            },\n"
                "        ),\n"
                "    }")
    return ("Error {\n"
            "        kind: Msg(\n"
            f"            \"Failed to render '{template_name}'\",\n"
            "        ),\n"
            "        source: Some(\n"
            "            Error {\n"
            "                kind: Msg(\n"
            f"                    \"{inner}\",\n"
            "                ),\n"
            "                source: None,\n"
            "            },\n"
            "        ),\n"
            "    }")

def rust_panic(location, message):
    pid=os.getpid()
    sys.stderr.write(f"\nthread 'main' ({pid}) panicked at {location}:\n{message}\nnote: run with `RUST_BACKTRACE=1` environment variable to display a backtrace\n")
    sys.stderr.flush()
    try: os.abort()
    except Exception: raise SystemExit(-6)

# ---------- Thumbnail (PNG only) ----------
def make_thumbnail(src, dest, max_size):
    try:
        data=src.read_bytes()
        if data.startswith(b'\x89PNG\r\n\x1a\n'):
            thumb=resize_png(data, max_size)
            if thumb: dest.write_bytes(thumb); return
        # fallback copy original
        dest.write_bytes(data)
    except Exception:
        try: shutil.copyfile(src,dest)
        except Exception: pass

def resize_png(data, max_size):
    # parse chunks
    try:
        pos=8; idat=b''; ihdr=None; plte=None; trns=None; other=[]
        while pos < len(data):
            length=struct.unpack(">I", data[pos:pos+4])[0]; typ=data[pos+4:pos+8]; chunk_data=data[pos+8:pos+8+length]; pos+=12+length
            if typ==b'IHDR': ihdr=chunk_data
            elif typ==b'IDAT': idat+=chunk_data
            elif typ==b'PLTE': plte=chunk_data
            elif typ==b'tRNS': trns=chunk_data
            if typ==b'IEND': break
        w,h,bit_depth,color_type,comp,filt,interlace=struct.unpack(">IIBBBBB", ihdr)
        if interlace!=0: return None
        raw=zlib.decompress(idat)
        # bytes per pixel approx
        channels={0:1,2:3,3:1,4:2,6:4}[color_type]
        if bit_depth==8: bpp=channels; row_bytes=w*channels
        elif bit_depth<8 and color_type==3: bpp=1; row_bytes=(w*bit_depth+7)//8
        elif bit_depth==16: bpp=channels*2; row_bytes=w*channels*2
        else: return None
        # unfilter
        rows=[]; prev=bytearray(row_bytes); offset=0
        for y in range(h):
            f=raw[offset]; offset+=1; cur=bytearray(raw[offset:offset+row_bytes]); offset+=row_bytes
            if f==1:
                for i in range(bpp,row_bytes): cur[i]=(cur[i]+cur[i-bpp])&255
            elif f==2:
                for i in range(row_bytes): cur[i]=(cur[i]+prev[i])&255
            elif f==3:
                for i in range(row_bytes):
                    a=cur[i-bpp] if i>=bpp else 0; cur[i]=(cur[i]+((a+prev[i])//2))&255
            elif f==4:
                for i in range(row_bytes):
                    a=cur[i-bpp] if i>=bpp else 0; b=prev[i]; c=prev[i-bpp] if i>=bpp else 0
                    p=a+b-c; pa=abs(p-a); pb=abs(p-b); pc=abs(p-c); pr=a if (pa<=pb and pa<=pc) else (b if pb<=pc else c)
                    cur[i]=(cur[i]+pr)&255
            rows.append(bytes(cur)); prev=cur
        # convert to RGBA rows pixel tuples
        pixels=[]
        if color_type==3 and bit_depth==8:
