        elif color_type==6 and bit_depth==8:
            for r in rows: pixels.append([tuple(r[i:i+4]) for i in range(0,len(r),4)])
        elif color_type==0 and bit_depth==8:
            for r in rows: pixels.append([(v,v,v,255) for v in r])
        elif color_type==4 and bit_depth==8:
            for r in rows: pixels.append([(r[i],r[i],r[i],r[i+1]) for i in range(0,len(r),2)])
        else:
            return None
        if max(w,h) <= max_size: new_w,new_h=w,h
        else:
            scale=max_size/max(w,h); new_w=max(1,int(w*scale+0.5)); new_h=max(1,int(h*scale+0.5))
