def format_tera_error(e, template_name, dest, engine):
    # Construct Rust Debug-like error string
    inner=str(e)
    # determine kind
    kind=getattr(e,'kind',None); func=getattr(e,'func',None)
    if kind=="CallFunction" and func:
        inner_msg=getattr(e,'inner',inner)
        return ("Error {\n"
                "        kind: Msg(\n"
                f"            \"Failed to render '{template_name}'\",\n"
                "        ),\n"
                "        source: Some(\n"
                "            Error {\n"
                "                kind: CallFunction(\n"
                f"                    \"{func}\",\n"
                "                ),\n"
                "                source: Some(\n"
                "                    Error {\n"
                "                        kind: Msg(\n"
                f"                            \"{inner_msg}\",\n"
                "                        ),\n"
                "                        source: None,\n"
                "                    },\n"
                "                ),\n"
                "            },\n"
                "        ),\n"
                "    }")
    return ("Error {\n"
            "        kind: Msg(\n"
            f"            \"Failed to render '{template_name}'\",\n"
            "        ),\n"
            "        source: Some(\n"
            "            Error {\n"
            "                kind: Msg(\n"
            f"                    \"{inner}\",\n"
            "                ),\n"
            "                source: None,\n"
            "            },\n"
            "        ),\n"
