def make_thumbnail(src, dest, max_size):
    try:
        data=src.read_bytes()
        if data.startswith(b'\x89PNG\r\n\x1a\n'):
            thumb=resize_png(data, max_size)
            if thumb: dest.write_bytes(thumb); return
