        channels={0:1,2:3,3:1,4:2,6:4}[color_type]
        if bit_depth==8: bpp=channels; row_bytes=w*channels
        elif bit_depth<8 and color_type==3: bpp=1; row_bytes=(w*bit_depth+7)//8
        elif bit_depth==16: bpp=channels*2; row_bytes=w*channels*2
        else: return None
        # unfilter
        rows=[]; prev=bytearray(row_bytes); offset=0
        for y in range(h):
            f=raw[offset]; offset+=1; cur=bytearray(raw[offset:offset+row_bytes]); offset+=row_bytes
            if f==1:
                for i in range(bpp,row_bytes): cur[i]=(cur[i]+cur[i-bpp])&255
            elif f==2:
                for i in range(row_bytes): cur[i]=(cur[i]+prev[i])&255
            elif f==3:
                for i in range(row_bytes):
                    a=cur[i-bpp] if i>=bpp else 0; cur[i]=(cur[i]+((a+prev[i])//2))&255
            elif f==4:
                for i in range(row_bytes):
                    a=cur[i-bpp] if i>=bpp else 0; b=prev[i]; c=prev[i-bpp] if i>=bpp else 0
                    p=a+b-c; pa=abs(p-a); pb=abs(p-b); pc=abs(p-c); pr=a if (pa<=pb and pa<=pc) else (b if pb<=pc else c)
                    cur[i]=(cur[i]+pr)&255
            rows.append(bytes(cur)); prev=cur
        # convert to RGBA rows pixel tuples
        pixels=[]
        if color_type==3 and bit_depth==8:
            palette=[tuple(plte[i:i+3]) for i in range(0,len(plte),3)]
            for r in rows:
                row=[]
                for idx in r:
                    rgb=palette[idx] if idx < len(palette) else (0,0,0); alpha=255
                    if trns and idx < len(trns): alpha=trns[idx]
                    row.append((*rgb,alpha))
                pixels.append(row)
        elif color_type==2 and bit_depth==8:
            for r in rows: pixels.append([tuple(r[i:i+3])+(255,) for i in range(0,len(r),3)])
        elif color_type==6 and bit_depth==8:
            for r in rows: pixels.append([tuple(r[i:i+4]) for i in range(0,len(r),4)])
        elif color_type==0 and bit_depth==8:
            for r in rows: pixels.append([(v,v,v,255) for v in r])
        elif color_type==4 and bit_depth==8:
            for r in rows: pixels.append([(r[i],r[i],r[i],r[i+1]) for i in range(0,len(r),2)])
        else:
            return None
        if max(w,h) <= max_size: new_w,new_h=w,h
        else:
            scale=max_size/max(w,h); new_w=max(1,int(w*scale+0.5)); new_h=max(1,int(h*scale+0.5))
            # observed: 52x60 -> 43x50 (round), 320x320->50x50
            new_w=max(1, round(w*scale)); new_h=max(1, round(h*scale))
        # resize bilinear
        out_rows=[]
        for y in range(new_h):
            src_y=(y+0.5)*h/new_h-0.5; y0=max(0,int(math.floor(src_y))); y1=min(h-1,y0+1); wy=src_y-y0
            if wy<0: wy=0
            row=[]
            for x in range(new_w):
                src_x=(x+0.5)*w/new_w-0.5; x0=max(0,int(math.floor(src_x))); x1=min(w-1,x0+1); wx=src_x-x0
                if wx<0: wx=0
                c00=pixels[y0][x0]; c10=pixels[y0][x1]; c01=pixels[y1][x0]; c11=pixels[y1][x1]
                vals=[]
                for ch in range(4):
                    v=(c00[ch]*(1-wx)*(1-wy)+c10[ch]*wx*(1-wy)+c01[ch]*(1-wx)*wy+c11[ch]*wx*wy)
                    vals.append(max(0,min(255,int(round(v)))))
                row.append(tuple(vals))
            out_rows.append(row)
        # encode PNG RGBA filter 0
        raw_out=b''.join(b'\x00'+b''.join(bytes(px) for px in row) for row in out_rows)
        def chunk(typ,chunk_data):
            c=struct.pack(">I",len(chunk_data))+typ+chunk_data; c+=struct.pack(">I", zlib.crc32(typ+chunk_data)&0xffffffff); return c
        png=b'\x89PNG\r\n\x1a\n'+chunk(b'IHDR',struct.pack(">IIBBBBB",new_w,new_h,8,6,0,0,0))+chunk(b'IDAT',zlib.compress(raw_out))+chunk(b'IEND',b'')
        return png
    except Exception:
        return None

