        server=ThreadingHTTPServer(('0.0.0.0',0), Handler); actual_host,actual_port=server.server_address[:2]; display_bind=f"0.0.0.0:{actual_port}"
    LOG.info("marmite::server", f"Server started at http://{display_bind}/ - Type ^C to stop.")
    try: server.serve_forever()
    except KeyboardInterrupt: pass
    return 0

def configure_logger(args):
    global LOG
    verbose=args.get('verbose',0)
    boost=any(args.get(k) for k in ('serve','watch','init_templates','start_theme','set_theme','generate_config','init_site'))
    if os.environ.get('RUST_LOG'):
        LOG=Logger(1)  # constructor reads env
    elif verbose>0: LOG.level=min(4,1+verbose)
    elif boost: LOG.level=2
    else: LOG.level=1

def main(argv=None):
    if argv is None: argv=sys.argv[1:]
    try:
        args=parse_cli(argv)
    except ClapExit as e:
        return e.code
    configure_logger(args)
    # init-site before existence
    if args.get('init_site'):
        return do_init_site(args)
    # input existence
    if not Path(args['input']).exists():
        LOG.error("marmite", f'Input folder does not exist: "{args["input"]}"'); return 1
    # dispatch
    try:
        if args.get('new') is not None: return do_new(args)
        if args.get('init_templates'): return do_init_templates(args)
        if args.get('start_theme') is not None: return do_start_theme(args)
        if args.get('set_theme') is not None: return do_set_theme(args)
        if args.get('generate_config'): return do_generate_config(args)
        if args.get('shortcodes'): return do_shortcodes(args)
        if args.get('show_urls'): return do_show_urls(args)
    except SiteError as e:
        LOG.error("marmite::site", str(e)); return 1
    # normal generation
    result=run_generation(args)
    if isinstance(result,int): return result
    site=result
    # watch/serve
    if args.get('watch'):
        LOG.info("marmite::site", f"Watching for changes in folder: {args['input']}")
        # watcher loop/thread
        import threading
        def watcher():
            prev=snapshot_input(args['input'], site.output_path)
            while True:
                time.sleep(1)
                cur=snapshot_input(args['input'], site.output_path)
                if cur!=prev:
                    time.sleep(1)
                    LOG.info("marmite::site", "Change detected. Rebuilding site...")
                    try: run_generation(args)
                    except SystemExit: pass
                    except Exception: pass
                    prev=snapshot_input(args['input'], site.output_path)
        if args.get('serve'):
            t=threading.Thread(target=watcher, daemon=True); t.start(); return serve_site(site,args)
        else:
            try: watcher()
            except KeyboardInterrupt: return 0
    if args.get('serve'):
        return serve_site(site,args)
    return 0

if __name__=='__main__':
    sys.exit(main())
PY"}

