import subprocess, pathlib, shutil, json, re, sys
ORIG="/workspace/executable"; MINE="/tmp/myexec"
def normalize(rel, data):
    if rel=="marmite.json":
        try:
            j=json.loads(data); j.pop("generated_at",None); j.pop("timestamp",None); j.pop("elapsed_time",None); return json.dumps(j,sort_keys=True).encode()
        except: return data
    if rel.endswith(".rss"):
        return re.sub(rb'<lastBuildDate>.*?</lastBuildDate>',b'',data)
    return data
def run_case(inp, name, args=None):
    args=args or []
    base=pathlib.Path(f"/tmp/diffmany/{name}"); shutil.rmtree(base, ignore_errors=True); base.mkdir(parents=True)
    ro=subprocess.run([ORIG]+args+[str(inp),str(base/"orig")], capture_output=True, text=True)
    rm=subprocess.run([MINE]+args+[str(inp),str(base/"mine")], capture_output=True, text=True)
    oo=base/"orig"; mo=base/"mine"
    ofiles=sorted(p.relative_to(oo).as_posix() for p in oo.rglob("*") if p.is_file()) if oo.exists() else []
    mfiles=sorted(p.relative_to(mo).as_posix() for p in mo.rglob("*") if p.is_file()) if mo.exists() else []
    diffs=[]
    for rel in sorted(set(ofiles)&set(mfiles)):
        if normalize(rel,(oo/rel).read_bytes())!=normalize(rel,(mo/rel).read_bytes()): diffs.append(rel)
    return {"name":name,"orig_rc":ro.returncode,"mine_rc":rm.returncode,"orig_err":ro.stderr,"mine_err":rm.stderr,"only_orig":sorted(set(ofiles)-set(mfiles)),"only_mine":sorted(set(mfiles)-set(ofiles)),"diffs":diffs,"orig_out":ro.stdout,"mine_out":rm.stdout}
def report(r):
    print(f"{r['name']}: rc {r['orig_rc']}/{r['mine_rc']} onlyO={r['only_orig'][:6]} onlyM={r['only_mine'][:6]} diffs={r['diffs'][:12]}")
    if r['orig_rc']!=r['mine_rc'] or (r['orig_err'][:200]!=r['mine_err'][:200] and r['orig_rc']!=0):
        print("  errO",r['orig_err'][:400]); print("  errM",r['mine_err'][:400])
