def _sc_sort_group(items_map, ord_val):
    # items_map dict name->list
    items=list(items_map.items())
    if ord_val=="asc":
        items=sorted(items, key=lambda kv: len(kv[1]))
    else:
        items=sorted(items, key=lambda kv: len(kv[1]), reverse=True)
    return items

