def normalize(s):
    return re.sub(r'\[\d{4}-\d\d-\d\dT\d\d:\d\d:\d\dZ ', '[TS ', s)
def run_both(name, setup_files, args_builder, env=None):
    results=[]
    for label,binpath in [("orig",ORIG),("mine",MINE)]:
        base=pathlib.Path(f"/tmp/modesdiff/{name}/{label}"); shutil.rmtree(base, ignore_errors=True); (base/"in").mkdir(parents=True)
        for rel,c in setup_files.items():
            p=base/"in"/rel; p.parent.mkdir(parents=True, exist_ok=True); p.write_bytes(c if isinstance(c,bytes) else c.encode())
        args=args_builder(base)
        r=subprocess.run([binpath]+args, capture_output=True, text=True, env={**__import__('os').environ, **(env or {})})
        files={}
        for p in sorted(base.rglob("*")):
            if p.is_file(): files[p.relative_to(base).as_posix()]=p.read_bytes()
        results.append((r,files))
    (ro,fo),(rm,fm)=results
    print(f"==={name} rc {ro.returncode}/{rm.returncode}")
    if normalize(ro.stdout)!=normalize(rm.stdout): print(" STDOUT O",repr(ro.stdout[:1000]),"\n STDOUT M",repr(rm.stdout[:1000]))
    if normalize(ro.stderr)!=normalize(rm.stderr): print(" STDERR O",repr(normalize(ro.stderr)[:1500]),"\n STDERR M",repr(normalize(rm.stderr)[:1500]))
    # files: ignore date in welcome filename? compare keys/contents except marmite dated file names normalized
    def norm_files(f):
        out={}
        for k,v in f.items():
            nk=re.sub(r'\d{4}-\d\d-\d\d', 'DATE', k); out[nk]=v
        return out
    fo2,fm2=norm_files(fo),norm_files(fm)
    if set(fo2)!=set(fm2): print(" files only O",sorted(set(fo2)-set(fm2))[:10]," only M",sorted(set(fm2)-set(fo2))[:10])
    for k in set(fo2)&set(fm2):
        if fo2[k]!=fm2[k]: print(" file diff",k, fo2[k][:200], fm2[k][:200])
